    "window.addEventListener('error', (event) => {"
    "try {"
    "const message = String((event && (event.error && event.error.stack || event.message)) || 'Unknown HttpBridge UI error');"
    "document.body.setAttribute('data-httpbridge-js-error', message);"
    "let banner = document.getElementById('httpbridge-js-error-banner');"
    "if (!banner) {"
    "banner = document.createElement('pre');"
    "banner.id = 'httpbridge-js-error-banner';"
    "banner.style.position = 'fixed';"
    "banner.style.left = '12px';"
    "banner.style.right = '12px';"
    "banner.style.bottom = '12px';"
    "banner.style.zIndex = '99999';"
    "banner.style.margin = '0';"
    "banner.style.padding = '12px 14px';"
    "banner.style.borderRadius = '12px';"
    "banner.style.background = 'rgba(120,20,20,.96)';"
    "banner.style.color = '#fff7f7';"
    "banner.style.fontSize = '12px';"
    "banner.style.lineHeight = '1.4';"
    "banner.style.whiteSpace = 'pre-wrap';"
    "banner.style.boxShadow = '0 10px 28px rgba(0,0,0,.28)';"
    "document.body.appendChild(banner);"
    "}"
    "banner.textContent = `HTTPBridge UI error\\n${message}`;"
    "} catch (_e) {}"
    "});"
    "const mainTopbar = document.getElementById('main-topbar');"
    "const sidebarEl = document.querySelector('.sidebar');"
    "const sidebarToggleBtn = document.getElementById('sidebar-toggle');"
    "const sidebarBackdrop = document.getElementById('sidebar-backdrop');"
    "function openSidebar(){if(sidebarEl)sidebarEl.classList.add('is-open');if(sidebarBackdrop)sidebarBackdrop.classList.add('is-open');}"
    "function closeSidebar(){if(sidebarEl)sidebarEl.classList.remove('is-open');if(sidebarBackdrop)sidebarBackdrop.classList.remove('is-open');}"
    "if(sidebarToggleBtn)sidebarToggleBtn.addEventListener('click',function(){sidebarEl&&sidebarEl.classList.contains('is-open')?closeSidebar():openSidebar();});"
    "if(sidebarBackdrop)sidebarBackdrop.addEventListener('click',closeSidebar);"
    "(function(){var txStart=0,tyStart=0,EDGE=30,THRESH=50;"
    "document.addEventListener('touchstart',function(e){txStart=e.touches[0].clientX;tyStart=e.touches[0].clientY;},{passive:true});"
    "document.addEventListener('touchend',function(e){var dx=e.changedTouches[0].clientX-txStart,dy=e.changedTouches[0].clientY-tyStart;"
    "if(Math.abs(dy)>Math.abs(dx))return;"
    "if(dx>THRESH&&txStart<EDGE){openSidebar();}"
    "else if(dx<-THRESH&&sidebarEl&&sidebarEl.classList.contains('is-open')){closeSidebar();}"
    "},{passive:true});})();"
