    "const getWorkspaceGoalCollapsedStorageKey = (sessionId) => `httpbridge:workspace-goal-collapsed:${String(sessionId || '').trim()}`;"
    "const readWorkspaceGoalCollapsed = (sessionId) => localStorage.getItem(getWorkspaceGoalCollapsedStorageKey(sessionId)) === '1';"
    "const writeWorkspaceGoalCollapsed = (sessionId, value) => localStorage.setItem(getWorkspaceGoalCollapsedStorageKey(sessionId), value ? '1' : '0');"
