    "if (goalPopoverOpen && settingsButton) { settingsButton.classList.remove('is-active'); settingsButton.classList.add('ghost'); settingsButton.setAttribute('aria-expanded','false'); }"
    "if (goalPopoverOpen) {"
    "if (goalEditorStatus) goalEditorStatus.textContent = sessionPermissionAllowed('update_goal') ? 'Goal updates are session-scoped.' : 'This session is SessionMap-only. Open a working session to edit its goal.';"
    "goalEditorDirty = false;"
