    "};"
    "const normalizeSessionPermissions = (raw) => {"
    "const defaults = { create_child_session: true, update_goal: true, send_prompt: true, auto_spawn_recovery: true, auto_resume: true };"
    "if (!raw || typeof raw !== 'object') return { ...defaults };"
    "const next = { ...defaults };"
    "for (const [key, value] of Object.entries(raw)) next[String(key)] = Boolean(value);"
    "return next;"
    "};"
    "const normalizeChildSessionSharing = (raw) => {"
    "const source = raw && typeof raw === 'object' ? raw : {};"
    "const normalizeList = (value) => Array.isArray(value) ? Array.from(new Set(value.map((item) => String(item || '').trim()).filter(Boolean))) : [];"
    "const mode = ['private','public','allowlist'].includes(String(source.mode || '').trim().toLowerCase()) ? String(source.mode || '').trim().toLowerCase() : 'private';"
    "const allowedUnitIds = normalizeList(source.allowed_source_unit_ids || source.allowed_source_template_ids);"
    "return { mode, allowed_source_session_ids: normalizeList(source.allowed_source_session_ids), allowed_source_unit_ids: allowedUnitIds, allowed_source_template_ids: allowedUnitIds };"
    "};"
    "const sessionPermissionAllowed = (operation) => Boolean(normalizeSessionPermissions(sessionPermissions)[String(operation || '').trim()]);"
    "const sessionUsesMapOnlyUI = () => String(sessionUiMode || 'standard').trim().toLowerCase() === 'map_only';"
    "const renderChildSessionSharingEditor = () => {"
    "const policy = normalizeChildSessionSharing(childSessionSharing);"
    "if (childSharingMode) childSharingMode.value = policy.mode;"
    "if (childSharingSessionIds) childSharingSessionIds.value = policy.allowed_source_session_ids.join('\\n');"
    "if (childSharingTemplateIds) childSharingTemplateIds.value = policy.allowed_source_unit_ids.join('\\n');"
    "if (childSharingStatus && !childSharingStatus.dataset.busy) {"
    "if (policy.mode === 'public') childSharingStatus.textContent = 'Any session owned by you may create child sessions here.';"
    "else if (policy.mode === 'allowlist') childSharingStatus.textContent = 'Only the listed sessions or units may create child sessions here.';"
    "else childSharingStatus.textContent = 'Child sessions are private to this session by default.';"
    "}"
    "if (childSharingForm) childSharingForm.classList.toggle('is-hidden', !sessionPermissionAllowed('create_child_session'));"
    "if (childSharingSaveButton) childSharingSaveButton.disabled = settingsMutationInFlight || !sessionPermissionAllowed('create_child_session');"
