    "if (goalEditorText) { goalEditorText.disabled = !canUpdateGoal; goalEditorText.placeholder = canUpdateGoal ? 'Describe the goal for this session' : 'This session is SessionMap-only. Open a working session, then edit the goal there.'; }"
    "if (goalSaveButton) goalSaveButton.disabled = goalMutationInFlight || !canUpdateGoal;"
    "if (goalToggleButton) goalToggleButton.disabled = goalMutationInFlight || !canUpdateGoal;"
    "if (goalResetCompletedButton) goalResetCompletedButton.disabled = goalMutationInFlight || !canUpdateGoal;"
    "if (goalAttachInput) goalAttachInput.disabled = !canUpdateGoal;"
    "if (composerText) { composerText.disabled = composerSubmitInFlight || !canSendPrompt; composerText.placeholder = canSendPrompt ? 'Send a message to the selected worker' : 'This session is SessionMap-only. Open a working session for replies.'; }"
    "if (composerFileInput) composerFileInput.disabled = composerSubmitInFlight || !canSendPrompt;"
    "if (composerSubmitButton) composerSubmitButton.disabled = composerSubmitInFlight || !canSendPrompt;"
    "if (!composerSubmitInFlight && composerStatus) composerStatus.textContent = canSendPrompt ? 'Prompt mode' : 'Prompt disabled for this session';"
    "if (goalBoardCreateForm) goalBoardCreateForm.classList.toggle('is-hidden', !canCreateChildSession);"
    "if (goalBoardCreateLabel) goalBoardCreateLabel.disabled = !canCreateChildSession;"
    "if (goalBoardCreateButton) goalBoardCreateButton.disabled = !canCreateChildSession;"
    "if (unitLauncherForm) Array.from(unitLauncherForm.elements || []).forEach((node) => { if ('disabled' in node) node.disabled = !canCreateChildSession; });"
    "if (goalBoardCreateStatus && !canCreateChildSession) goalBoardCreateStatus.textContent = 'Child session creation is disabled for this session';"
    "else if (goalBoardCreateStatus && !goalBoardCreateStatus.dataset.busy && !goalBoardCreateStatus.dataset.lastState) goalBoardCreateStatus.textContent = 'Creates a child session under the active session.';"
    "if (unitLauncherStatus && !canCreateChildSession && !unitLauncherStatus.dataset.busy) unitLauncherStatus.textContent = 'Unit launch is disabled from this session. You can still inspect unit state and reopen prior sessions.';"
    "renderChildSessionSharingEditor();"
    "if (sessionUsesMapOnlyUI() && !sessionMapOpen && !unitsPaneOpen && !nodesPaneOpen && !requestsPaneOpen && !accountRegisterOpen && !accountSettingsOpen) setSessionMapOpen(true);"
