    "const sessionDisplayQuery = () => { const bits = []; const scopeQuery = sessionScopeQuery(); const windowQuery = sessionWindowQuery(); if (scopeQuery) bits.push(scopeQuery); if (windowQuery) bits.push(windowQuery); return bits.join('&'); };"
