    "const formatElapsedSince = (value) => { const ms = parseTimestampMs(value); if (!ms) return ''; const seconds = Math.max(0, Math.floor((Date.now() - ms) / 1000)); if (seconds < 60) return `${seconds}s elapsed`; const minutes = Math.floor(seconds / 60); if (minutes < 60) return `${minutes}m elapsed`; const hours = Math.floor(minutes / 60); if (hours < 48) return `${hours}h elapsed`; const days = Math.floor(hours / 24); if (days < 60) return `${days}d elapsed`; const months = Math.floor(days / 30); if (months < 24) return `${months}mo elapsed`; return `${Math.floor(days / 365)}y elapsed`; };"
