    "unitLauncherList.innerHTML = launcherCatalogUnits.map((unit) => { const unitId = launcherUnitId(unit); const state = unit?.state && typeof unit.state === 'object' ? unit.state : {}; const scheduleStatus = unit?.schedule_status && typeof unit.schedule_status === 'object' ? unit.schedule_status : {}; const tags = []; if (String(unit?.launcher?.ui_url || '').trim()) tags.push('Interface'); if (Boolean(state?.registered)) tags.push('Registered'); if (Boolean(unit?.launcher?.schedule?.enabled)) tags.push(`${String(scheduleStatus?.timezone || 'UTC')} ${String(scheduleStatus?.daily_time || '').trim()}`.trim()); if (String(state?.last_session_id || '').trim()) tags.push(`last ${String(state?.last_session_id || '').trim()}`); if (String((state?.schedule_state || {}).last_error || scheduleStatus?.last_error || '').trim()) tags.push('Error'); return `<button type='button' class='unit-launcher-card${unitId === String(activeUnitLauncherId || '') ? ' is-active' : ''}' data-unit-id='${escapeHtml(unitId)}'><div class='unit-launcher-card-title'>${escapeHtml(String(unit?.display_name || unitId || ''))}</div><div class='unit-launcher-card-meta'>${escapeHtml(String(unit?.unit_kind || unit?.kind || 'unit'))} | ${escapeHtml(String(unit?.package_id || unit?.plugin_id || 'core'))}</div><div class='unit-launcher-card-copy'>${escapeHtml(String(unit?.description || 'Create a session from this unit.'))}</div><div class='unit-launcher-card-state'>${escapeHtml(String(state?.workspace_path || '').trim() || 'No unit workspace recorded yet')}</div><div class='unit-launcher-card-tags'>${tags.map((tag) => `<span class='unit-launcher-service-pill'>${escapeHtml(String(tag || ''))}</span>`).join('')}</div></button>`; }).join('');"
