    "};"
    "const orderSessionSummaries = (summaries) => {"
    "const list = Array.isArray(summaries) ? summaries.filter(Boolean) : [];"
    "const byParent = new Map();"
    "for (const summary of list) {"
    "const parentId = String(summary?.parent_session_id || '').trim();"
    "if (!byParent.has(parentId)) byParent.set(parentId, []);"
    "byParent.get(parentId).push(summary);"
    "}"
    "for (const siblings of byParent.values()) siblings.sort((a, b) => {"
    "const aPinned = sessionIsUnitOrResident(a) ? 1 : 0;"
