    "};"
    "const sessionRuntimeState = (summary) => String(summary?.runtime_execution_state || '').trim().toLowerCase() || (Boolean(summary?.runtime_in_progress) || Boolean(summary?.agent_running) || String(summary?.goal_manager_state || '').trim().toLowerCase() === 'running' ? 'running' : 'idle');"
