    "};"
    "const normalizeAgentPriority = (value) => {"
    "const source = Array.isArray(value) ? value : ['codex', 'claude', 'gemini', 'border'];"
    "const next = [];"
    "const seen = new Set();"
    "let borderSeen = false;"
    "const active = [];"
    "const saved = [];"
    "source.forEach((raw) => {"
    "const token = String(raw || '').trim().toLowerCase();"
    "if (!token) return;"
    "const normalized = token;"
    "if (seen.has(normalized)) return;"
    "seen.add(normalized);"
    "if (normalized === 'border') { borderSeen = true; return; }"
    "if (borderSeen) saved.push(normalized); else active.push(normalized);"
    "});"
    "for (const provider of ['codex', 'claude', 'gemini']) {"
    "if (!seen.has(provider)) saved.push(provider);"
    "}"
    "next.push(...active);"
    "if (borderSeen || saved.length) next.push('border');"
    "next.push(...saved);"
    "return next.length ? next : ['codex', 'claude', 'gemini', 'border'];"
    "};"
    "const syncAgentPriorityInput = () => {"
    "if (agentPriorityInput) agentPriorityInput.value = normalizeAgentPriority(agentPriority).join('\\n');"
    "};"
    "const parseAgentPriorityInput = () => normalizeAgentPriority(agentPriority);"
    "const syncGoalManagerPriorityInput = () => {"
    "if (goalManagerPriorityInput) goalManagerPriorityInput.value = normalizeAgentPriority(goalManagerPriority).join('\\n');"
    "};"
    "const parseGoalManagerPriorityInput = () => normalizeAgentPriority(goalManagerPriority);"
    "const moveAgentPriorityItem = (fromIndex, toIndex) => {"
    "const ordered = normalizeAgentPriority(agentPriority);"
    "if (fromIndex === toIndex || fromIndex < 0 || toIndex < 0 || fromIndex >= ordered.length || toIndex >= ordered.length) return;"
    "const next = [...ordered];"
    "const [item] = next.splice(fromIndex, 1);"
    "next.splice(toIndex, 0, item);"
    "agentPriority = next;"
    "syncAgentPriorityInput();"
    "renderAgentPriority();"
    "};"
    "const activeAgentPriority = (value) => {"
    "const ordered = normalizeAgentPriority(value);"
    "const active = [];"
    "for (const kind of ordered) {"
    "if (kind === 'border') break;"
    "if (kind) active.push(kind);"
    "}"
    "return active;"
    "};"
    "let agentPriorityDragIndex = -1;"
    "let agentPriorityDropIndex = -1;"
    "const syncAgentPriorityDropTarget = () => {"
    "if (!agentPriorityList) return;"
    "agentPriorityList.querySelectorAll('.agent-priority-item').forEach((node) => {"
    "if (!(node instanceof HTMLElement)) return;"
    "node.classList.toggle('is-drop-target', Number.parseInt(String(node.dataset.priorityIndex || ''), 10) === agentPriorityDropIndex);"
    "});"
    "};"
    "const renderAgentPriority = () => {"
    "if (!agentPriorityList) return;"
    "agentPriority = normalizeAgentPriority(agentPriority);"
    "syncAgentPriorityInput();"
    "const labels = { codex: 'Codex', claude: 'Claude Code', gemini: 'Gemini', border: 'Border' };"
    "const activeKinds = activeAgentPriority(agentPriority);"
    "agentPriorityList.replaceChildren();"
    "let activeRank = 1;"
    "agentPriority.forEach((kind, index) => {"
    "const row = document.createElement('div');"
    "row.className = 'agent-priority-item';"
    "row.dataset.priorityIndex = String(index);"
    "if (index === agentPriorityDropIndex) row.classList.add('is-drop-target');"
    "row.classList.add('is-draggable');"
    "row.draggable = true;"
    "if (kind === 'border') {"
    "row.classList.add('is-border');"
    "row.innerHTML = `<span class='priority-handle' aria-hidden='true'>≡</span><span class='priority-rank'>·</span><span class='priority-label'>Active / saved divider</span><span class='priority-state'>below this line stays saved only</span><span class='priority-controls'><button class='toolbar-button ghost priority-move' type='button' data-priority-move='up' data-priority-index='${index}' aria-label='Move divider up'>↑</button><button class='toolbar-button ghost priority-move' type='button' data-priority-move='down' data-priority-index='${index}' aria-label='Move divider down'>↓</button></span>`;"
    "} else {"
    "const inactive = activeKinds.includes(kind) ? '' : ' is-inactive';"
    "if (inactive) row.classList.add('is-inactive');"
    "const rankText = activeKinds.includes(kind) ? `${activeRank++}.` : '·';"
    "const stateText = activeKinds.includes(kind) ? 'active' : 'inactive';"
    "row.innerHTML = `<span class='priority-handle' aria-hidden='true'>≡</span><span class='priority-rank'>${rankText}</span><span class='priority-label'>${labels[kind] || kind}</span><span class='priority-state'>${stateText}</span><span class='priority-controls'><button class='toolbar-button ghost priority-move' type='button' data-priority-move='up' data-priority-index='${index}' aria-label='Move ${labels[kind] || kind} up'>↑</button><button class='toolbar-button ghost priority-move' type='button' data-priority-move='down' data-priority-index='${index}' aria-label='Move ${labels[kind] || kind} down'>↓</button></span>`;"
    "}"
    "row.addEventListener('dragstart', (event) => { agentPriorityDragIndex = index; agentPriorityDropIndex = index; row.classList.add('is-dragging'); syncAgentPriorityDropTarget(); if (event.dataTransfer) { event.dataTransfer.effectAllowed = 'move'; event.dataTransfer.setData('text/plain', String(index)); } });"
    "row.addEventListener('dragend', () => { agentPriorityDragIndex = -1; agentPriorityDropIndex = -1; renderAgentPriority(); });"
    "row.addEventListener('dragover', (event) => { event.preventDefault(); if (agentPriorityDragIndex < 0) return; agentPriorityDropIndex = index; syncAgentPriorityDropTarget(); if (event.dataTransfer) event.dataTransfer.dropEffect = 'move'; });"
    "row.addEventListener('drop', (event) => { event.preventDefault(); const fromIndex = agentPriorityDragIndex >= 0 ? agentPriorityDragIndex : Number.parseInt(String(event.dataTransfer?.getData('text/plain') || ''), 10); const toIndex = index; agentPriorityDragIndex = -1; agentPriorityDropIndex = -1; if (Number.isFinite(fromIndex)) moveAgentPriorityItem(fromIndex, toIndex); });"
    "agentPriorityList.appendChild(row);"
    "});"
    "if (agentPriorityMeta) agentPriorityMeta.textContent = activeKinds.length ? `Dispatch order: ${activeKinds.map((kind) => labels[kind] || kind).join(' → ')}` : 'No runnable local provider is above the divider. The runtime will fall back to local defaults.';"
    "};"
    "const moveGoalManagerPriorityItem = (fromIndex, toIndex) => {"
    "const ordered = normalizeAgentPriority(goalManagerPriority);"
    "if (fromIndex === toIndex || fromIndex < 0 || toIndex < 0 || fromIndex >= ordered.length || toIndex >= ordered.length) return;"
    "const next = [...ordered];"
    "const [item] = next.splice(fromIndex, 1);"
    "next.splice(toIndex, 0, item);"
    "goalManagerPriority = next;"
    "syncGoalManagerPriorityInput();"
    "renderGoalManagerPriority();"
    "};"
    "const renderGoalManagerPriority = () => {"
    "if (!goalManagerPriorityList) return;"
    "goalManagerPriority = normalizeAgentPriority(goalManagerPriority);"
    "syncGoalManagerPriorityInput();"
    "const labels = { codex: 'Codex', claude: 'Claude Code', gemini: 'Gemini', border: 'Border' };"
    "const activeKinds = activeAgentPriority(goalManagerPriority);"
    "goalManagerPriorityList.replaceChildren();"
    "let activeRank = 1;"
    "goalManagerPriority.forEach((kind, index) => {"
    "const row = document.createElement('div');"
    "row.className = 'agent-priority-item';"
    "if (kind === 'border') {"
    "row.classList.add('is-border');"
    "row.innerHTML = `<span class='priority-rank'>·</span><span class='priority-label'>Active / saved divider</span><span class='priority-state'>below this line stays saved only</span><span class='priority-controls'><button class='toolbar-button ghost priority-move' type='button' data-gm-priority-move='up' data-priority-index='${index}' aria-label='Move GoalManager divider up'>↑</button><button class='toolbar-button ghost priority-move' type='button' data-gm-priority-move='down' data-priority-index='${index}' aria-label='Move GoalManager divider down'>↓</button></span>`;"
    "} else {"
    "const inactive = activeKinds.includes(kind) ? '' : ' is-inactive';"
    "if (inactive) row.classList.add('is-inactive');"
    "const rankText = activeKinds.includes(kind) ? `${activeRank++}.` : '·';"
    "const stateText = activeKinds.includes(kind) ? 'active' : 'inactive';"
    "row.innerHTML = `<span class='priority-rank'>${rankText}</span><span class='priority-label'>${labels[kind] || kind}</span><span class='priority-state'>${stateText}</span><span class='priority-controls'><button class='toolbar-button ghost priority-move' type='button' data-gm-priority-move='up' data-priority-index='${index}' aria-label='Move GoalManager ${labels[kind] || kind} up'>↑</button><button class='toolbar-button ghost priority-move' type='button' data-gm-priority-move='down' data-priority-index='${index}' aria-label='Move GoalManager ${labels[kind] || kind} down'>↓</button></span>`;"
    "}"
    "goalManagerPriorityList.appendChild(row);"
    "});"
    "if (goalManagerPriorityMeta) goalManagerPriorityMeta.textContent = activeKinds.length ? `GoalManager order: ${activeKinds.map((kind) => labels[kind] || kind).join(' → ')}` : 'No GoalManager provider is above the divider. The runtime will fall back to native defaults.';"
    "};"
    "const renderSessionPriority = () => {"
    "if (sessionPriorityInput) sessionPriorityInput.value = String(sessionPriority);"
    "if (sessionPriorityValue) sessionPriorityValue.textContent = String(sessionPriority);"
    "};"
    "window.handleSettingsSave = async () => {"
