    "try {"
    "const newSessionPriority = sessionPriorityInput ? (Number.parseInt(String(sessionPriorityInput.value), 10) || 50) : sessionPriority;"
    "agentPriority = parseAgentPriorityInput();"
    "goalManagerPriority = parseGoalManagerPriorityInput();"
    "const payload = await postGoalStateJson({"
    "auto_resume_enabled: settingsAutoResumeEnabled.checked,"
