    "session_priority: newSessionPriority,"
    "});"
    "sessionPriority = Number.isFinite(Number(payload.session_priority)) ? Number(payload.session_priority) : newSessionPriority;"
    "if (Array.isArray(payload.agent_priority) && payload.agent_priority.length) agentPriority = payload.agent_priority;"
    "if (Array.isArray(payload.goal_manager_priority) && payload.goal_manager_priority.length) goalManagerPriority = payload.goal_manager_priority;"
