    "let lastWorkspaceNavRenderKey = '';"
    "let lastGoalBoardRenderKey = '';"
    "const workspaceNavRenderKey = (summaries) => JSON.stringify((Array.isArray(summaries) ? summaries : []).map((summary) => ({"
    "sid: String(summary?.session_id || ''),"
    "label: String(summary?.label || ''),"
    "active: Boolean(summary?.goal_active),"
    "completed: Boolean(summary?.goal_completed),"
    "progress: String(summary?.goal_progress_state || ''),"
    "runtime: String(summary?.runtime_execution_state || ''),"
    "runtime_in_progress: Boolean(summary?.runtime_in_progress),"
    "agent_running: Boolean(summary?.agent_running),"
    "goal_manager_state: String(summary?.goal_manager_state || ''),"
    "audit: String(summary?.goal_audit_state || ''),"
    "wait_status: String(summary?.user_response_wait_status || ''),"
    "wait_active: Boolean(summary?.user_response_wait_active),"
    "created_by_username: String(summary?.created_by_username || ''),"
    "origin_session_id: String(summary?.origin_session_id || ''),"
    "selected: String(summary?.session_id || '') === String(activeSessionId || ''),"
    "})));"
    "const goalBoardRenderKey = (summaries) => JSON.stringify({"
    "open: Boolean(sessionMapOpen),"
    "viewMode: sessionMapViewMode,"
    "filters: sessionMapFilters,"
    "timeWindowSeconds: sessionMapWindowSeconds,"
    "active: String(activeSessionId || ''),"
    "snapshot: Array.isArray(sessionMapSnapshotWorkspaceIds) ? sessionMapSnapshotWorkspaceIds : [],"
    "workerCounts: workerCounts || {},"
    "cards: (Array.isArray(summaries) ? summaries : []).map((summary) => ({"
    "sid: String(summary?.session_id || ''),"
    "label: String(summary?.label || ''),"
    "created_at: String(summary?.created_at || ''),"
    "updated_at: String(summary?.updated_at || ''),"
    "registered_at: String(summary?.registered_at || ''),"
    "goal_updated_at: String(summary?.goal_updated_at || ''),"
    "resident_unit_session: Boolean(summary?.resident_unit_session),"
    "associated_unit_id: String(summary?.associated_unit_id || ''),"
    "associated_template_id: String(summary?.associated_template_id || ''),"
    "associated_unit_display_name: String(summary?.associated_unit_display_name || ''),"
    "has_associated_unit_file: Boolean(summary?.has_associated_unit_file),"
    "goal: String(summary?.goal_text || ''),"
    "goal_active: Boolean(summary?.goal_active),"
    "goal_completed: Boolean(summary?.goal_completed),"
    "goal_progress_state: String(summary?.goal_progress_state || ''),"
    "goal_audit_state: String(summary?.goal_audit_state || ''),"
    "runtime_execution_state: String(summary?.runtime_execution_state || ''),"
    "runtime_in_progress: Boolean(summary?.runtime_in_progress),"
    "agent_running: Boolean(summary?.agent_running),"
    "goal_manager_state: String(summary?.goal_manager_state || ''),"
    "auto_resume_enabled: Boolean(summary?.auto_resume_enabled),"
    "wait_status: String(summary?.user_response_wait_status || ''),"
    "wait_active: Boolean(summary?.user_response_wait_active),"
    "preferred_provider: String(summary?.preferred_provider || ''),"
    "worker_provider: String(summary?.worker?.provider || ''),"
    "worker_slot: summary?.worker?.slot == null ? null : String(summary?.worker?.slot),"
    "worker_service_id: String(summary?.worker?.service_id || ''),"
    "goal_worker_slot: summary?.goal_manager_worker?.slot == null ? null : String(summary?.goal_manager_worker?.slot),"
    "goal_worker_service_id: String(summary?.goal_manager_worker?.service_id || ''),"
    "parent_session_id: String(summary?.parent_session_id || ''),"
    "created_by_username: String(summary?.created_by_username || ''),"
    "origin_session_id: String(summary?.origin_session_id || ''),"
    "session_group: String(summary?.session_group || ''),"
    "session_ui_mode: String(summary?.session_ui_mode || ''),"
    "})),"
    "});"
    "const sessionTimestampMs = (summary) => {"
    "for (const key of ['updated_at', 'goal_updated_at', 'created_at']) {"
    "const value = String(summary?.[key] || '').trim();"
    "if (!value) continue;"
    "const parsed = Date.parse(value);"
    "if (Number.isFinite(parsed)) return parsed;"
    "}"
    "return 0;"
    "};"
    "const sessionIsUnitOrResident = (summary) => {"
    "const group = String(summary?.session_group || '').trim().toLowerCase();"
    "const uiMode = String(summary?.session_ui_mode || '').trim().toLowerCase();"
    "const sid = String(summary?.session_id || '').trim().toLowerCase();"
    "const label = String(summary?.label || '').trim().toLowerCase();"
    "if (Boolean(summary?.resident_unit_session)) return true;"
    "if (['system', 'unit', 'resident', 'root'].includes(group)) return true;"
    "if (['session_map', 'sessionmap', 'map_only'].includes(uiMode)) return true;"
    "return sid === 'default' || sid.includes('unit') || label.includes('unit');"
    "};"
    "const sessionWithinMapTimeWindow = (summary) => {"
    "const windowSeconds = Math.max(0, Number(sessionMapWindowSeconds) || 0);"
    "if (windowSeconds === 0) return true;"
    "if (sessionIsUnitOrResident(summary)) return true;"
    "const ts = sessionTimestampMs(summary);"
    "if (!ts) return true;"
    "return (Date.now() - ts) <= windowSeconds * 1000;"
    "};"
    "const sessionMatchesMapFilters = (summary) => {"
    "if (sessionMapFilters.activeOnly && !summary?.goal_active) return false;"
    "const progressState = String(summary?.goal_progress_state || (summary?.goal_completed ? 'complete' : 'in_progress')).trim().toLowerCase();"
    "if (sessionMapFilters.inProgressOnly && progressState !== 'in_progress') return false;"
    "if (sessionMapFilters.autoScheduleOnly && !summary?.auto_resume_enabled) return false;"
    "if (sessionMapFilters.awaitingUserOnly) {"
    "const waitStatus = String(summary?.user_response_wait_status || 'idle').trim().toLowerCase();"
    "const waitingWithoutUserReply = Boolean(summary?.user_response_wait_active) || waitStatus === 'timed_out';"
    "if (!waitingWithoutUserReply) return false;"
    "}"
    "return true;"
    "};"
    "const sessionMapRootSessionId = () => sessionMapRootMode === 'session' ? String(activeSessionId || '').trim() : '';"
    "const sessionTreeSessions = (summaries, rootSessionId) => {"
    "const list = Array.isArray(summaries) ? summaries.filter(Boolean) : [];"
    "const rootId = String(rootSessionId || '').trim();"
    "if (!rootId) return list;"
    "const byParent = new Map();"
    "const byId = new Map();"
    "for (const summary of list) {"
    "const sid = String(summary?.session_id || '').trim();"
    "if (!sid) continue;"
    "byId.set(sid, summary);"
    "const pid = String(summary?.parent_session_id || '').trim();"
    "if (!byParent.has(pid)) byParent.set(pid, []);"
    "byParent.get(pid).push(summary);"
    "}"
    "if (!byId.has(rootId)) return list;"
    "const result = [];"
    "const stack = [rootId];"
    "const seen = new Set();"
    "while (stack.length) {"
    "const sid = String(stack.shift() || '').trim();"
    "if (!sid || seen.has(sid)) continue;"
    "seen.add(sid);"
    "const summary = byId.get(sid);"
    "if (summary) result.push(summary);"
    "for (const child of byParent.get(sid) || []) stack.push(String(child?.session_id || '').trim());"
    "}"
    "return rootId ? result.filter((summary) => String(summary?.session_id || '').trim() !== rootId) : result;"
    "};"
    "const filteredGoalBoardSessions = (summaries) => {"
    "const workspaceSummariesById = new Map((Array.isArray(summaries) ? summaries : []).map((s) => [String(s?.session_id || '').trim(), s]));"
    "const baseList = sessionMapOpen && sessionMapSnapshotWorkspaceIds.length ? sessionMapSnapshotWorkspaceIds.map((id) => workspaceSummariesById.get(id)).filter(Boolean) : (Array.isArray(summaries) ? summaries : []);"
    "const scopedList = sessionTreeSessions(baseList, sessionMapRootSessionId());"
    "return scopedList.filter((summary) => sessionWithinMapTimeWindow(summary) && sessionMatchesMapFilters(summary));"
    "};"
    "const activeGoalBoardFilterLabels = () => {"
    "const labels = [];"
    "labels.push(sessionMapRootMode === 'session' ? 'Current Tree' : 'All Sessions');"
    "if (sessionMapFilters.activeOnly) labels.push('Active');"
    "if (sessionMapFilters.inProgressOnly) labels.push('In Progress');"
    "if (sessionMapFilters.awaitingUserOnly) labels.push('Awaiting User');"
    "if (sessionMapFilters.autoScheduleOnly) labels.push('AutoSchedule');"
    "if (Number(sessionMapWindowSeconds) > 0) labels.push(goalBoardTimeWindow && goalBoardTimeWindow.selectedOptions?.[0] ? String(goalBoardTimeWindow.selectedOptions[0].textContent || '').trim() : `${String(sessionMapWindowSeconds)}s`);"
    "return labels;"
    "};"
    "const renderSessionMapFilters = () => {"
    "if (goalBoardFilterActive) goalBoardFilterActive.checked = Boolean(sessionMapFilters.activeOnly);"
    "if (goalBoardFilterInProgress) goalBoardFilterInProgress.checked = Boolean(sessionMapFilters.inProgressOnly);"
    "if (goalBoardFilterAwaitingUser) goalBoardFilterAwaitingUser.checked = Boolean(sessionMapFilters.awaitingUserOnly);"
    "if (goalBoardFilterAutoSchedule) goalBoardFilterAutoSchedule.checked = Boolean(sessionMapFilters.autoScheduleOnly);"
    "if (goalBoardTimeWindow) goalBoardTimeWindow.value = String(Math.max(0, Number(sessionMapWindowSeconds) || 0));"
    "if (workspaceTimeWindow) workspaceTimeWindow.value = String(Math.max(0, Number(sessionMapWindowSeconds) || 0));"
    "};"
    "const persistSessionMapFilters = () => {"
    "localStorage.setItem(sessionMapFiltersKey, JSON.stringify(sessionMapFilters));"
    "};"
    "const setSessionMapRootMode = (mode) => {"
    "sessionMapRootMode = mode === 'all' ? 'all' : 'session';"
    "localStorage.setItem(sessionMapRootModeKey, sessionMapRootMode);"
    "lastGoalBoardRenderKey = '';"
    "renderGoalBoard();"
    "if (goalBoardScopeSession) goalBoardScopeSession.classList.toggle('is-active', sessionMapRootMode === 'session');"
    "if (goalBoardScopeAll) goalBoardScopeAll.classList.toggle('is-active', sessionMapRootMode === 'all');"
    "};"
    "const setSessionMapFilters = (nextFilters) => {"
    "sessionMapFilters = {"
    "activeOnly: Boolean(nextFilters?.activeOnly),"
    "inProgressOnly: Boolean(nextFilters?.inProgressOnly),"
    "awaitingUserOnly: Boolean(nextFilters?.awaitingUserOnly),"
    "autoScheduleOnly: Boolean(nextFilters?.autoScheduleOnly),"
    "};"
    "persistSessionMapFilters();"
    "renderSessionMapFilters();"
    "lastGoalBoardRenderKey = '';"
    "renderGoalBoard();"
    "};"
    "const setSessionMapTimeWindow = (value) => {"
    "const parsed = Number.parseInt(String(value || ''), 10);"
    "sessionMapWindowSeconds = Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;"
    "localStorage.setItem(sessionMapWindowSecondsKey, String(sessionMapWindowSeconds));"
    "renderSessionMapFilters();"
    "lastGoalBoardRenderKey = '';"
    "renderGoalBoard();"
    "};"
    "renderSessionMapFilters();"
    "const renderWorkspaceNavList = () => {"
    "if (!workspaceNavList) return;"
    "const summaries = orderSessionSummaries(workspaceSummaries);"
    "const renderKey = workspaceNavRenderKey(summaries);"
    "if (renderKey === lastWorkspaceNavRenderKey) return;"
    "lastWorkspaceNavRenderKey = renderKey;"
    "const scrollState = captureElementScrollState(workspaceNavList);"
    "const nodes = summaries.map((summary) => {"
    "const sid = String(summary?.session_id || '').trim();"
    "if (!sid) return null;"
    "const isActive = sid === String(activeSessionId || '');"
    "const link = document.createElement('a');"
    "link.className = `workspace-nav-item${isActive ? ' is-active' : ''}`;"
    "link.href = sessionPathFor(sid);"
    "link.addEventListener('click', (ev) => { ev.preventDefault(); switchToSession(sid); });"
    "const head = document.createElement('span');"
    "head.className = 'workspace-nav-head';"
    "const title = document.createElement('span');"
    "title.className = 'workspace-nav-title';"
    "title.style.paddingLeft = `${Math.max(0, Number(summary?._treeDepth || 0)) * 14}px`;"
    "title.textContent = String(summary?.label || sid);"
    "const signals = document.createElement('span');"
    "signals.className = 'workspace-nav-signals';"
    "signals.setAttribute('aria-label', 'Session goal status');"
    "const activeSignal = document.createElement('span');"
    "activeSignal.className = `workspace-signal workspace-signal-active${summary?.goal_active ? ' is-on' : ''}`;"
    "activeSignal.textContent = '●';"
    "activeSignal.title = 'Goal active state';"
    "const completedSignal = document.createElement('span');"
    "completedSignal.className = `workspace-signal workspace-signal-completed${summary?.goal_completed ? ' is-on' : ''}`;"
    "completedSignal.textContent = '●';"
    "completedSignal.title = 'Goal completed state';"
    "const auditState = String(summary?.goal_audit_state || 'all_clear').trim().toLowerCase();"
    "const auditSignal = document.createElement('span');"
    "auditSignal.className = `workspace-signal workspace-signal-audit${auditState === 'panic' ? ' is-panic' : (auditState === 'needs_compact' ? ' is-warn' : ' is-on')}`;"
    "auditSignal.textContent = '●';"
    "auditSignal.title = `Audit state: ${auditStateLabel(auditState)}`;"
    "signals.append(activeSignal, completedSignal, auditSignal);"
    "head.append(title, signals);"
    "const meta = document.createElement('span');"
    "meta.className = 'workspace-nav-meta';"
    "meta.textContent = sid;"
    "const origin = document.createElement('span');"
    "origin.className = 'workspace-nav-origin';"
    "origin.textContent = String(summary?.origin_session_id || '').trim() ? `from ${String(summary?.created_by_username || '').trim() || 'unknown'} via ${String(summary?.origin_session_id || '').trim()}` : `created by ${String(summary?.created_by_username || '').trim() || 'unknown'}`;"
    "const waitStatus = String(summary?.user_response_wait_status || 'idle');"
    "const waitActive = Boolean(summary?.user_response_wait_active);"
    "const status = document.createElement('span');"
    "status.className = 'workspace-nav-status';"
    "const addStatusChip = (text, className = '') => { const chip = document.createElement('span'); chip.className = `workspace-nav-chip${className}`; chip.textContent = text; status.appendChild(chip); };"
    "const navProgress = goalBoardProgressLabel(summary);"
    "addStatusChip(summary?.goal_active ? 'Goal Active' : 'Goal Inactive', summary?.goal_active ? ' is-active' : '');"
    "addStatusChip(navProgress, navProgress === 'Goal Completed' ? ' is-complete' : '');"
    "addStatusChip(sessionRuntimeLabel(summary));"
    "addStatusChip(auditStateLabel(auditState));"
    "link.append(head, meta, origin, status);"
    "const waitSignal = document.createElement('span');"
    "waitSignal.className = `workspace-signal workspace-signal-wait${waitStatus !== 'idle' ? ' is-on' : ''}${waitActive ? ' is-waiting' : ''}${waitStatus === 'timed_out' ? ' is-timeout' : ''}`;"
    "waitSignal.textContent = '●';"
    "waitSignal.title = 'User response wait state';"
    "signals.append(waitSignal);"
    "return link;"
    "}).filter(Boolean);"
    "workspaceNavList.replaceChildren(...nodes);"
    "restoreElementScrollPosition(workspaceNavList, scrollState);"
    "};"
    "const goalBoardCountsText = () => {"
    "const codex = workerCounts?.codex || {};"
    "const claude = workerCounts?.claude || {};"
    "const gemini = workerCounts?.gemini || {};"
    "return `Codex ${String(codex.running || 0)} active / ${String(codex.active_turns || 0)} busy (${String(codex.replying_turns || 0)} replying, ${String(codex.reviewing_turns || 0)} reviewing) | Claude ${String(claude.running || 0)} active / ${String(claude.active_turns || 0)} busy (${String(claude.replying_turns || 0)} replying, ${String(claude.reviewing_turns || 0)} reviewing) | Gemini ${String(gemini.running || 0)} active / ${String(gemini.active_turns || 0)} busy (${String(gemini.replying_turns || 0)} replying, ${String(gemini.reviewing_turns || 0)} reviewing)`;"
    "};"
    "const buildGoalSessionCard = (summary) => {"
    "const link = document.createElement('a');"
    "const worker = summary?.worker || null;"
    "const workerProvider = ['codex', 'claude', 'gemini'].includes(String(worker?.provider || '').trim().toLowerCase()) ? String(worker.provider).trim().toLowerCase() : String(summary?.preferred_provider || 'codex');"
    "const workerSlot = worker?.slot == null ? '·' : String(worker.slot);"
    "const workerServiceId = String(worker?.service_id || summary?.bound_service_id || '').trim();"
    "const goalWorker = summary?.goal_manager_worker || null;"
    "const goalWorkerSlot = goalWorker?.slot == null ? '·' : String(goalWorker.slot);"
    "const goalWorkerServiceId = String(goalWorker?.service_id || '').trim();"
    "link.className = 'goal-session-card';"
    "if (String(summary?.session_id || '') === activeSessionId) link.classList.add('is-active-workspace');"
    "if (summary?.agent_running) link.classList.add('is-agent-running');"
    "if (String(summary?.goal_manager_state || '') === 'running') link.classList.add('is-goal-running');"
    "if (String(summary?.goal_audit_state || '').trim().toLowerCase() === 'panic') link.classList.add('is-goal-panic');"
    "if (!summary?.goal_active) link.classList.add('is-goal-inactive');"
    "link.href = sessionPathFor(String(summary?.session_id || ''));"
    "const registeredAt = String(summary?.registered_at || summary?.created_at || '').trim();"
    "const goalUpdatedAt = String(summary?.goal_updated_at || summary?.updated_at || '').trim();"
    "const registeredExact = formatExactTimestamp(registeredAt);"
    "const goalUpdatedExact = formatExactTimestamp(goalUpdatedAt);"
    "const elapsedLabel = formatElapsedSince(registeredAt) || 'elapsed unknown';"
    "const unitId = String(summary?.associated_unit_id || summary?.associated_template_id || '').trim();"
    "const unitDisplay = String(summary?.associated_unit_display_name || unitId || '').trim();"
    "const isResidentUnit = Boolean(summary?.resident_unit_session);"
    "const hasAssociatedUnit = Boolean(summary?.has_associated_unit_file || unitId);"
    "link.title = `Open this session${registeredExact ? ` | registered ${registeredExact}` : ''}${goalUpdatedExact ? ` | goal updated ${goalUpdatedExact}` : ''}${unitId ? ` | unit ${unitId}` : ''}`;"
    "link.addEventListener('click', (ev) => { ev.preventDefault(); switchToSession(String(summary?.session_id || '')); });"
    "const leftMarkerTitle = workerServiceId ? `${summary?.agent_running ? 'Agent replying now' : 'Bound/selected worker'}: ${workerServiceId}` : `${summary?.agent_running ? 'Agent replying now' : 'Bound/selected worker'}`;"
    "const rightMarkerTitle = goalWorkerServiceId ? `GoalManager running: ${goalWorkerServiceId}` : 'GoalManager running';"
    "const leftMarker = `<span class='goal-marker goal-marker-left${workerProvider === 'claude' ? ' is-claude' : ''}${summary?.worker ? '' : ' is-idle'}' title='${escapeHtml(leftMarkerTitle)}'>${workerSlot}</span>`;"
    "const rightMarker = `<span class='goal-marker goal-marker-right${String(summary?.goal_manager_state || '') === 'running' ? '' : ' is-hidden'}' title='${escapeHtml(rightMarkerTitle)}'>${goalWorkerSlot}</span>`;"
    "const goalText = String(summary?.goal_text || '').trim();"
    "const waitStatus = String(summary?.user_response_wait_status || 'idle');"
    "const waitActive = Boolean(summary?.user_response_wait_active);"
    "const auditState = String(summary?.goal_audit_state || 'all_clear').trim().toLowerCase();"
    "const auditBadge = `<span class='goal-session-badge ${auditStateBadgeClass(auditState)}'>${auditStateLabel(auditState)}</span>`;"
    "const autoScheduleBadge = summary?.auto_resume_enabled ? `<span class='goal-session-badge'>AutoSchedule</span>` : '';"
    "const residentBadge = isResidentUnit ? `<span class='goal-session-badge' title='Resident Unit-backed session'>Resident Unit</span>` : '';"
    "const unitBadge = hasAssociatedUnit ? `<span class='goal-session-badge' title='Associated unit: ${escapeHtml(unitId || unitDisplay)}'>Unit${unitDisplay ? ` · ${escapeHtml(unitDisplay)}` : ''}</span>` : '';"
    "const goalHtml = goalText ? escapeHtml(goalText) : `<span class='goal-session-empty'>No goal</span>`;"
    "const waitBadge = waitStatus !== 'idle' ? `<span class='goal-session-badge${waitActive ? ' is-warn' : ''}'>${waitActive ? 'Waiting User Response' : (waitStatus === 'timed_out' ? 'Wait Timed Out' : 'Wait Recorded')}</span>` : '';"
    "const originMeta = String(summary?.origin_session_id || '').trim() ? ` | from ${String(summary?.created_by_username || '').trim() || 'unknown'} via ${String(summary?.origin_session_id || '').trim()}` : ` | created by ${String(summary?.created_by_username || '').trim() || 'unknown'}`;"
    "const workerMetaBits = [];"
    "if (workerServiceId) workerMetaBits.push(`worker ${workerServiceId}`);"
    "if (goalWorkerServiceId) workerMetaBits.push(`gm ${goalWorkerServiceId}`);"
    "const workerMeta = workerMetaBits.length ? ` | ${workerMetaBits.join(' | ')}` : '';"
    "link.innerHTML = `${leftMarker}${rightMarker}<div class='goal-session-card-head'><div class='goal-session-title'>${escapeHtml(summary?.label || summary?.session_id || '')}</div></div><div class='goal-session-meta'>${escapeHtml(summary?.username ? summary.username + ' · ' : '')}${escapeHtml(summary?.session_id || '')}${escapeHtml(originMeta)}${escapeHtml(workerMeta)}</div><div class='goal-session-timing'><span class='goal-session-elapsed' title='Registered at ${escapeHtml(registeredExact || registeredAt || 'unknown')}'>${escapeHtml(elapsedLabel)}</span><span class='goal-session-updated' title='Goal last updated at ${escapeHtml(goalUpdatedExact || goalUpdatedAt || 'unknown')}'>Goal updated ${escapeHtml(goalUpdatedExact || goalUpdatedAt || 'unknown')}</span></div><div class='goal-session-goal'>${goalHtml}</div><div class='goal-session-state'><span class='goal-session-badge${goalBoardActivityBadgeClass(summary)}'>${summary?.goal_active ? 'Goal Active' : 'Goal Inactive'}</span><span class='goal-session-badge${goalBoardProgressLabel(summary) === 'Goal Completed' ? ' is-done' : ''}'>${goalBoardProgressLabel(summary)}</span><span class='goal-session-badge${sessionRuntimeBadgeClass(summary)}'>${sessionRuntimeLabel(summary)}</span>${auditBadge}${residentBadge}${unitBadge}${autoScheduleBadge}${waitBadge}</div>`;"
    "return link;"
    "};"
    "const renderGoalBoard = () => {"
    "const workspaceSummariesList = Array.isArray(workspaceSummaries) ? workspaceSummaries : [];"
    "const renderKey = goalBoardRenderKey(workspaceSummariesList);"
    "if (renderKey === lastGoalBoardRenderKey) return;"
    "lastGoalBoardRenderKey = renderKey;"
    "const scrollState = captureElementScrollState(goalBoardGrid);"
    "goalBoardCounts.replaceChildren();"
    "for (const provider of ['codex', 'claude', 'gemini']) {"
    "const item = workerCounts?.[provider] || {};"
    "const pill = document.createElement('div');"
    "pill.className = `goal-worker-pill${provider === 'claude' ? ' is-claude' : ''}`;"
    "pill.innerHTML = `<span class='goal-worker-dot'></span><span>${goalBoardProviderLabel(provider)}</span><strong>${String(item.running || 0)}</strong><span>${String(item.active_turns || 0)} busy</span><span>${String(item.replying_turns || 0)} replying / ${String(item.reviewing_turns || 0)} reviewing</span>`;"
    "goalBoardCounts.appendChild(pill);"
    "}"
    "const visibleList = orderSessionSummaries(filteredGoalBoardSessions(workspaceSummariesList));"
    "if (goalBoardScopeSession) goalBoardScopeSession.classList.toggle('is-active', sessionMapRootMode === 'session');"
    "if (goalBoardScopeAll) goalBoardScopeAll.classList.toggle('is-active', sessionMapRootMode === 'all');"
    "const filterLabels = activeGoalBoardFilterLabels();"
    "const rootLabel = sessionMapRootMode === 'session' ? `Children of: ${String(workspaceLabel || activeSessionId || 'current session')}` : 'Tree root: all visible sessions';"
    "const emptyStateText = sessionMapRootMode === 'session' ? 'No child sessions match the current Session Map filters.' : 'No sessions match the current Session Map filters.';"
    "goalBoardMeta.textContent = filterLabels.length ? `${goalBoardCountsText()} | ${rootLabel} | ${String(visibleList.length)} shown with ${filterLabels.join(' + ')} filters` : `${goalBoardCountsText()} | ${rootLabel} | ${String(visibleList.length)} sessions shown`;"
    "if (goalBoardViewDag) goalBoardViewDag.classList.toggle('is-active', sessionMapViewMode === 'dag');"
    "if (goalBoardViewGrid) goalBoardViewGrid.classList.toggle('is-active', sessionMapViewMode === 'grid');"
    "if (sessionMapViewMode === 'grid') {"
    "goalBoardGrid.className = 'goal-board-grid is-grid-view';"
    "goalBoardGrid.replaceChildren(...(visibleList.length ? visibleList.map(buildGoalSessionCard) : [Object.assign(document.createElement('div'), { className: 'goal-board-empty', textContent: emptyStateText })]));"
    "restoreElementScrollPosition(goalBoardGrid, scrollState);"
    "return;"
    "}"
    "/* DAG mode: DFS tree, indented by depth (right-triangle layout) */"
    "goalBoardGrid.className = 'goal-board-grid';"
    "const visibleById = new Map(visibleList.map((s) => [String(s?.session_id || ''), s]));"
    "const items = [];"
    "const visited = new Set();"
    "const dfs = (id, depth) => {"
    "if (visited.has(id)) return;"
    "visited.add(id);"
    "const summary = visibleById.get(id);"
    "if (!summary) return;"
    "const card = buildGoalSessionCard(summary);"
    "const indent = depth * 36;"
    "card.style.marginLeft = `${indent}px`;"
    "card.style.width = `calc(100% - ${indent}px)`;"
    "if (depth > 0) card.style.borderLeft = '3px solid rgba(31,26,20,.15)';"
    "items.push(card);"
    "for (const s of visibleList) { if (String(s?.parent_session_id || '') === id) dfs(String(s?.session_id || ''), depth + 1); }"
    "};"
    "for (const s of visibleList) { const pid = String(s?.parent_session_id || '').trim(); if (!pid || !visibleById.has(pid)) dfs(String(s?.session_id || ''), 0); }"
    "for (const s of visibleList) { dfs(String(s?.session_id || ''), 0); }"
    "goalBoardGrid.replaceChildren(...(items.length ? items : [Object.assign(document.createElement('div'), { className: 'goal-board-empty', textContent: emptyStateText })]));"
    "restoreElementScrollPosition(goalBoardGrid, scrollState);"
    "};"
    "let _refreshNetworkNodesInFlight = false;"
    "const renderNetworkNodes = (localNode, peers) => {"
    "if (!nodesList) return;"
    "const peerList = Array.isArray(peers) ? peers : [];"
    "if (nodesPaneMeta) nodesPaneMeta.textContent = localNode ? `Local node ${String(localNode?.node_id || '').trim() || '(unknown)'} with ${peerList.length} connected peer records.` : `${peerList.length} connected peer records.`;"
    "if (nodesPaneCounts) { nodesPaneCounts.replaceChildren(); const pill = document.createElement('div'); pill.className = 'goal-worker-pill'; pill.innerHTML = `<span class='goal-worker-dot'></span><span>Peers</span><strong>${String(peerList.length)}</strong><span>${localNode ? 'local descriptor reachable' : 'local descriptor unavailable'}</span>`; nodesPaneCounts.appendChild(pill); }"
    "const cards = [];"
    "if (localNode) {"
    "const card = document.createElement('div');"
    "card.className = 'network-card';"
    "card.innerHTML = `<div class='network-card-title'>Local Node</div><div class='network-card-meta'>node_id: ${escapeHtml(String(localNode?.node_id || ''))}</div><div class='network-card-meta'>peer_id: ${escapeHtml(String(localNode?.peer_id || ''))}</div><div class='network-card-meta'>base_url: ${escapeHtml(String(localNode?.base_url || ''))}</div>`;"
    "cards.push(card);"
    "}"
    "for (const peer of peerList) {"
    "const card = document.createElement('div');"
    "card.className = 'network-card';"
    "card.innerHTML = `<div class='network-card-title'>${escapeHtml(String(peer?.node_id || peer?.peer_id || 'Peer Node'))}</div><div class='network-card-meta'>peer_id: ${escapeHtml(String(peer?.peer_id || ''))}</div><div class='network-card-meta'>base_url: ${escapeHtml(String(peer?.base_url || ''))}</div><div class='network-card-meta'>updated_at: ${escapeHtml(String(peer?.updated_at || peer?.started_at || ''))}</div>`;"
    "cards.push(card);"
    "}"
    "nodesList.replaceChildren(...(cards.length ? cards : [Object.assign(document.createElement('div'), { className: 'goal-board-empty', textContent: 'No connected nodes are recorded yet.' })]));"
    "};"
    "const refreshNetworkNodes = async () => {"
    "if (_refreshNetworkNodesInFlight) return;"
    "_refreshNetworkNodesInFlight = true;"
    "try {"
    "const [localRes, peersRes] = await Promise.all([fetch(`/peer/ping?_=${Date.now()}`, { cache: 'no-store' }), fetch(`/federation/peers?_=${Date.now()}`, { cache: 'no-store' })]);"
    "const localPayload = await localRes.json().catch(() => ({}));"
    "const peersPayload = await peersRes.json().catch(() => ({}));"
    "renderNetworkNodes(localRes.ok ? localPayload : null, peersRes.ok ? peersPayload?.peers : []);"
    "if (nodesConnectStatus && !nodesConnectStatus.dataset.busy) nodesConnectStatus.textContent = peersRes.ok ? 'Network node list refreshed.' : 'Peer list refresh failed.';"
    "} catch (error) {"
    "if (nodesConnectStatus && !nodesConnectStatus.dataset.busy) nodesConnectStatus.textContent = `Network refresh failed: ${error instanceof Error ? error.message : 'network error'}`;"
    "} finally {"
    "_refreshNetworkNodesInFlight = false;"
    "}"
    "};"
    "const renderUserRequests = () => {"
    "if (!requestsList) return;"
    "const summaries = orderSessionSummaries(Array.isArray(workspaceSummaries) ? workspaceSummaries : []);"
    "const requestItems = summaries.filter((summary) => String(summary?.user_response_wait_request_id || summary?.user_response_wait_status || '').trim() && String(summary?.user_response_wait_status || 'idle') !== 'idle');"
    "const activeCount = requestItems.filter((summary) => Boolean(summary?.user_response_wait_active)).length;"
    "if (requestsPaneMeta) requestsPaneMeta.textContent = `${String(requestItems.length)} request records visible, ${String(activeCount)} actively waiting for user input.`;"
    "if (requestsPaneCounts) { requestsPaneCounts.replaceChildren(); const pill = document.createElement('div'); pill.className = 'goal-worker-pill'; pill.innerHTML = `<span class='goal-worker-dot'></span><span>Waiting</span><strong>${String(activeCount)}</strong><span>${String(requestItems.length)} total</span>`; requestsPaneCounts.appendChild(pill); }"
    "const cards = requestItems.map((summary) => {"
    "const sid = String(summary?.session_id || '').trim();"
    "const requestId = String(summary?.user_response_wait_request_id || '').trim();"
    "const status = String(summary?.user_response_wait_status || 'idle').trim();"
    "const prompt = String(summary?.user_response_wait_prompt_text || summary?.user_response_wait_reason || '').trim();"
    "const card = document.createElement('button');"
    "card.type = 'button';"
    "card.className = 'network-card';"
    "card.innerHTML = `<div class='network-card-title'>${escapeHtml(String(summary?.label || sid || 'Session'))}</div><div class='network-card-meta'>request_id: ${escapeHtml(requestId || '(not recorded)')}</div><div class='network-card-meta'>status: ${escapeHtml(status)}${summary?.user_response_wait_active ? ' / active' : ''}</div><div class='network-card-meta'>session_id: ${escapeHtml(sid)}</div><div class='network-card-meta'>${escapeHtml(prompt || 'No request text recorded in the session summary.')}</div>`;"
    "card.addEventListener('click', (event) => { event.preventDefault(); switchToSession(sid); });"
    "return card;"
    "});"
    "requestsList.replaceChildren(...(cards.length ? cards : [Object.assign(document.createElement('div'), { className: 'goal-board-empty', textContent: 'No user response requests are recorded in visible sessions.' })]));"
    "};"
    "const refreshSessionMapSnapshot = (nextWorkspaceSummaries) => {"
    "if (!sessionMapOpen) return;"
    "if (!Array.isArray(nextWorkspaceSummaries)) return;"
    "const nextSessionIds = new Set("
    "nextWorkspaceSummaries"
    "    .map((summary) => String(summary?.session_id || '').trim())"
    "    .filter(Boolean),"
    ");"
    "const mergedSessionIds = new Set(sessionMapSnapshotWorkspaceIds);"
    "for (const sessionId of nextSessionIds) {"
    "mergedSessionIds.add(sessionId);"
    "}"
    "sessionMapSnapshotWorkspaceIds = Array.from(mergedSessionIds);"
    "};"
    "let _refreshSessionIndexInFlight = false;"
    "const refreshSessionIndex = async () => {"
    "if (_refreshSessionIndexInFlight) return;"
    "_refreshSessionIndexInFlight = true;"
    "try {"
    "const displayQuery = sessionDisplayQuery();"
    "const response = await fetch(`/sessions?${displayQuery}${displayQuery ? '&' : ''}_=${Date.now()}`, { cache: 'no-store' });"
    "const payload = await response.json().catch(() => ({}));"
    "if (!response.ok) return;"
    "if (Array.isArray(payload.session_summaries)) {"
    "workspaceSummaries = payload.session_summaries;"
    "renderWorkspaceNavList();"
    "if (sessionMapOpen) {"
    "refreshSessionMapSnapshot(payload.session_summaries);"
    "renderGoalBoard();"
    "}"
    "}"
    "if (payload.worker_counts) workerCounts = payload.worker_counts;"
    "} catch (_error) {"
    "/* ignore transient session index refresh errors */"
    "} finally {"
    "_refreshSessionIndexInFlight = false;"
    "}"
    "};"
    "const renderProviderState = () => {"
    "providerSelect.value = preferredProvider;"
    "providerStatus.textContent = ({ codex: 'This session will dispatch new prompts to Codex workers.', claude: 'This session will dispatch new prompts to Claude Code workers.', gemini: 'This session will dispatch new prompts to Gemini workers.' }[preferredProvider] || 'This session will dispatch new prompts to Codex workers.');"
    "manualCompactButton.disabled = !manualCompactAvailableForService(boundServiceId);"
    "renderSessionCapabilityState();"
    "};"
    "const renderAgentStatus = () => {"
    "const popoverServiceId = String(activeAgentPopoverServiceId || boundServiceId || '').trim();"
    "const isWritableAgent = Boolean(popoverServiceId) && popoverServiceId === boundServiceId;"
    "agentStatusValue.textContent = `${popoverServiceId && popoverServiceId.includes('claude') ? 'Claude Code' : (popoverServiceId && popoverServiceId.includes('gemini') ? 'Gemini' : providerLabel())} | ${auditStateLabel(goalAuditState)}`;"
    "const bits = [popoverServiceId ? `agent ${popoverServiceId}` : 'No bound service'];"
    "if (goalAuditState === 'needs_compact') bits.push('Compact requested before normal continuation');"
    "else if (goalAuditState === 'panic') bits.push('Dispatch is blocked until recovery');"
    "else bits.push('Agent can continue processing this session');"
    "if (!isWritableAgent) bits.push('read-only view');"
    "agentStatusMeta.textContent = bits.join(' | ');"
    "};"
    "const deriveAgentMessageEventText = (entry) => {"
    "if (!entry || !entry.event || entry.event_type !== 'item.completed') return null;"
    "const item = entry.event.item;"
    "if (!item || item.type !== 'agent_message') return null;"
    "const raw = String(item.text || '').trim();"
    "if (!raw) return '';"
    "try { const parsed = JSON.parse(raw); if (parsed && typeof parsed === 'object') { for (const key of Object.keys(parsed)) { const normalized = String(key).toLowerCase().replaceAll('_', ''); if ((normalized === 'assistanttext' || normalized === 'assistant') && typeof parsed[key] === 'string') return parsed[key].trim(); } } } catch (_error) {}"
    "return raw;"
    "};"
    "const shouldRenderEventJson = (entry) => {"
    "if (!entry || !entry.event) return false;"
    "return deriveAgentMessageEventText(entry) === null;"
    "};"
    "const entryDisplayText = (entry) => {"
    "const agentText = deriveAgentMessageEventText(entry);"
    "if (agentText !== null) return agentText;"
    "return entry.text || '';"
    "};"
    "const extractGoalEventType = (entry) => String(entry?.event_type || (entry?.event && entry.event.type) || '');"
    "const isGoalManagerEntry = (entry) => {"
    "const eventType = extractGoalEventType(entry);"
    "return eventType.startsWith('service.goal_') || eventType.startsWith('service.goal_manager_compact_') || eventType === 'service.post_turn_followup_started' || eventType === 'service.post_turn_followup_failed';"
    "};"
    "const plainBlockKind = (entry) => {"
    "const direction = String(entry?.direction || '').trim();"
    "if (direction === 'out' || direction === 'user') return 'user_block';"
    "if (direction === 'session_input') return 'system_block';"
    "if ((direction === 'event' || direction === 'agent') && !isGoalManagerEntry(entry) && !isAgentTurnRelatedEntry(entry)) return 'system_block';"
    "return null;"
    "};"
    "const renderEntry = (entry) => {"
    "const li = document.createElement('li');"
    "const goalManagerEntry = isGoalManagerEntry(entry);"
    "li.className = `entry ${goalManagerEntry ? 'entry-goal-manager' : `entry-${entry.direction || 'event'}`}`;"
    "const bubble = document.createElement('div');"
    "bubble.className = 'bubble';"
    "if (entry.context_left_percent !== undefined) { const badge = document.createElement('div'); badge.className = 'ctx-badge'; const bits = [`${entry.context_left_percent}% left`]; if (entry.context_compaction) bits.push(entry.context_compaction); badge.textContent = bits.join(' | '); bubble.appendChild(badge); }"
    "const role = document.createElement('div');"
    "role.className = 'role';"
    "const normalizedDirection = String(entry.direction || '').trim();"
    "role.textContent = goalManagerEntry ? 'GoalManager' : (({"
    "    out: 'User',"
    "    user: 'User',"
    "    in: 'Worker',"
    "    event: 'Event',"
    "    agent: 'AgentMessage',"
    "    session_input: 'SessionInput',"
    "})[normalizedDirection || 'event'] || normalizedDirection || 'event');"
    "bubble.appendChild(role);"
    "const text = document.createElement('div');"
    "text.className = 'text';"
    "text.textContent = entryDisplayText(entry);"
    "bubble.appendChild(text);"
    "const metaBits = [];"
    "if (entry.event_type) metaBits.push(entry.event_type);"
    "if (entry.from) metaBits.push(`from ${entry.from}`);"
    "if (entry.to) metaBits.push(`to ${entry.to}`);"
    "if (metaBits.length) { const meta = document.createElement('div'); meta.className = 'meta'; meta.textContent = metaBits.join(' | '); bubble.appendChild(meta); }"
    "if (shouldRenderEventJson(entry)) { const pre = document.createElement('pre'); pre.className = 'event-json'; pre.textContent = JSON.stringify(entry.event, null, 2); bubble.appendChild(pre); }"
    "li.appendChild(bubble);"
    "return li;"
    "};"
    "const entryServiceId = (entry) => String(entry?.service_id || entry?.from || '').trim();"
    "const isAgentTurnRelatedEntry = (entry) => {"
    "if (!entry || isGoalManagerEntry(entry) || entry.direction === 'out') return false;"
    "const eventType = String(entry?.event_type || '');"
    "if (entry.direction === 'in' || entry.direction === 'session_input') return Boolean(entryServiceId(entry));"
    "if (entry.direction === 'event' || entry.direction === 'agent') {"
    "return Boolean(entryServiceId(entry)) || eventType === 'usage' || String(eventType).startsWith('service.');"
    "}"
    "return false;"
    "};"
    "const turnLogLabel = (entry) => {"
    "const eventType = String(entry?.event_type || '');"
    "if (eventType === 'agent.turn_started') return 'response started';"
    "if (eventType === 'thread.started') return 'thread started';"
    "if (eventType === 'turn.started') return 'turn started';"
    "if (eventType === 'turn.completed') return 'turn completed';"
    "if (eventType.startsWith('item.')) return eventType;"
    "if (entry.direction === 'session_input') return String(entry.kind || 'session input');"
    "if (entry.direction === 'in') return 'assistant reply';"
    "return eventType || entry.direction || 'event';"
    "};"
    "const runtimeJournalSummaryText = (summary) => {"
    "const count = Number(summary?.entry_count || 0);"
    "const first = String(summary?.first_ts || '').trim();"
    "const last = String(summary?.last_ts || '').trim();"
    "const agents = Array.isArray(summary?.service_ids) ? summary.service_ids.length : 0;"
    "const parts = [`${count} ${count === 1 ? 'entry' : 'entries'}`];"
    "if (agents) parts.push(`${agents} ${agents === 1 ? 'agent' : 'agents'}`);"
    "if (first) parts.push(`started ${first}`);"
    "if (last && last !== first) parts.push(`latest ${last}`);"
    "return parts.join(' | ');"
    "};"
    "const renderRuntimeJournalMeta = () => {"
    "if (!runtimeJournalMeta) return;"
    "runtimeJournalMeta.textContent = runtimeJournalSummaryText(runtimeJournalSummary);"
    "};"
    "const renderRuntimeJournalEntries = (items) => {"
    "if (!runtimeJournalLog) return;"
    "const entriesToRender = Array.isArray(items) ? items : [];"
    "runtimeJournalLog.replaceChildren();"
    "if (!entriesToRender.length) {"
    "const empty = document.createElement('div');"
    "empty.className = 'runtime-journal-empty';"
    "empty.textContent = 'No runtime events recorded for this session.';"
    "runtimeJournalLog.appendChild(empty);"
    "return;"
    "}"
    "for (const item of entriesToRender) {"
    "const row = document.createElement('div');"
    "row.className = 'runtime-journal-entry';"
    "const head = document.createElement('div');"
    "head.className = 'runtime-journal-entry-head';"
    "const left = document.createElement('span');"
    "left.textContent = String(item?.event_type || 'runtime.event');"
    "head.appendChild(left);"
    "const right = document.createElement('span');"
    "right.textContent = String(item?.ts || '');"
    "head.appendChild(right);"
    "row.appendChild(head);"
    "const nested = item?.entry && typeof item.entry === 'object' ? item.entry : null;"
    "const text = document.createElement('div');"
    "text.className = 'runtime-journal-entry-text';"
    "text.textContent = nested ? entryDisplayText(nested) : JSON.stringify(item, null, 2);"
