    "}"
    "};"
    "const fetchRuntimeJournal = async ({ entries: includeEntries = true } = {}) => {"
    "const url = `/session/runtime-log?session_id=${encodeURIComponent(activeSessionId)}&entries=${includeEntries ? '1' : '0'}&limit=500&${sessionWindowQuery()}&_=${Date.now()}`;"
    "const response = await fetch(url, { cache: 'no-store' });"
    "const payload = await response.json().catch(() => ({}));"
    "if (!response.ok || !payload.ok) throw new Error(String(payload.error || `HTTP ${response.status}`));"
    "runtimeJournalSummary = payload.summary && typeof payload.summary === 'object' ? payload.summary : runtimeJournalSummary;"
    "renderRuntimeJournalMeta();"
    "if (includeEntries) { renderRuntimeJournalEntries(payload.entries || []); runtimeJournalLoadedForSession = activeSessionId; }"
    "return payload;"
    "};"
    "const goalManagerClusterState = (cluster) => {"
    "const lastEntry = cluster.entries[cluster.entries.length - 1] || null;"
    "const eventType = String(lastEntry?.event_type || '');"
    "if (eventType === 'service.goal_manager_compact_failed' || eventType === 'service.post_turn_followup_failed') return { text: 'Failed', className: 'is-signal-red', meta: 'Manager review hit an error' };"
    "if (eventType === 'service.goal_manager_compact_completed') return { text: 'Completed', className: 'is-complete', meta: 'Manager finished this review cycle' };"
    "const hasParseRetry = cluster.entries.some((e) => String(e?.event_type || '').includes('goal_audit_parse_retry'));"
    "if (hasParseRetry) return { text: 'Parse Retry', className: 'is-signal-yellow', meta: 'GoalManager output could not be parsed; retrying' };"
    "return { text: 'Reviewing', className: 'is-signal-blue', meta: 'Manager is actively reviewing this session' };"
    "};"
    "const agentInlineStatusBits = (cluster) => {"
    "const status = deriveContextStatusForService(cluster.serviceId) || (cluster.serviceId === boundServiceId ? (contextStatus || {}) : {});"
    "const bits = [];"
    "if (status.left_percent) bits.push(`${String(status.left_percent)}% left`);"
    "if (status.used_percent) bits.push(`${String(status.used_percent)}% used`);"
    "if (status.compaction) bits.push(`compaction ${String(status.compaction)}`);"
    "if (cluster.serviceId === boundServiceId) bits.push(`audit ${auditStateLabel(goalAuditState)}`);"
    "if (cluster.serviceId && boundServiceId && cluster.serviceId !== boundServiceId) bits.push('read-only');"
    "return bits;"
    "};"
    "const renderTurnCluster = (cluster) => {"
    "const li = document.createElement('li');"
