    "meta.textContent = isGoalManagerCluster ? goalManagerClusterState(cluster).meta : (cluster.completed ? 'TurnCompleted received for this response' : (cluster.replyEntry ? 'Assistant reply received. Waiting for TurnCompleted and trailing events.' : 'Agent is responding and streaming events here'));"
    "headCopy.appendChild(meta);"
    "if (!isGoalManagerCluster) {"
