    "}"
    "headCopy.appendChild(inlineStatus);"
    "}"
    "head.appendChild(headCopy);"
    "const badges = document.createElement('div');"
    "badges.className = 'turn-cluster-badges';"
    "const providerBadge = document.createElement('span');"
    "providerBadge.className = 'goal-badge';"
    "providerBadge.textContent = isGoalManagerCluster ? 'GoalManager' : (cluster.serviceId && cluster.serviceId.startsWith('session-skill-') ? 'Session Skill' : (cluster.serviceId && cluster.serviceId.includes('claude') ? 'Claude Code' : (cluster.serviceId && cluster.serviceId.includes('gemini') ? 'Gemini' : 'Codex')));"
    "badges.appendChild(providerBadge);"
    "if (!isGoalManagerCluster && cluster.serviceId && boundServiceId && cluster.serviceId === boundServiceId) {"
    "const auditBadge = document.createElement('span');"
    "auditBadge.className = `goal-badge ${goalAuditState === 'needs_compact' ? 'is-signal-yellow' : (goalAuditState === 'panic' ? 'is-signal-red' : 'is-signal-blue')}`;"
    "auditBadge.textContent = auditStateLabel(goalAuditState);"
    "badges.appendChild(auditBadge);"
    "}"
    "const progressBadge = document.createElement('span');"
    "if (isGoalManagerCluster) {"
    "const state = goalManagerClusterState(cluster);"
    "progressBadge.className = `goal-badge ${state.className}`;"
    "progressBadge.textContent = state.text;"
    "} else {"
    "progressBadge.className = `goal-badge${cluster.completed ? ' is-complete' : ''}`;"
    "progressBadge.textContent = cluster.completed ? 'TurnCompleted' : 'In Progress';"
    "}"
    "badges.appendChild(progressBadge);"
    "if (!isGoalManagerCluster) {"
    "const controlsButton = document.createElement('button');"
    "controlsButton.type = 'button';"
    "controlsButton.className = 'toolbar-button ghost';"
    "controlsButton.dataset.agentControlsButton = '1';"
    "controlsButton.dataset.agentServiceId = String(cluster.serviceId || '');"
