    "controlsButton.style.zIndex = '4';"
    "controlsButton.style.pointerEvents = 'auto';"
    "controlsButton.onclick = () => { setAgentPopoverOpen(true, cluster.serviceId); return false; };"
    "controlsButton.textContent = 'Agent';"
    "controlsButton.addEventListener('click', (event) => { event.preventDefault(); event.stopPropagation(); setAgentPopoverOpen(true, cluster.serviceId); });"
    "badges.appendChild(controlsButton);"
    "}"
    "head.appendChild(badges);"
    "bubble.appendChild(head);"
    "const reply = document.createElement('div');"
    "reply.className = `turn-cluster-reply${cluster.replyEntry ? '' : ' is-pending'}`;"
    "reply.textContent = isGoalManagerCluster ? entryDisplayText(cluster.entries[cluster.entries.length - 1] || {}) : (cluster.replyEntry ? entryDisplayText(cluster.replyEntry) : 'Waiting for the final assistant_text / TurnCompleted payload.');"
    "if (isGoalManagerCluster) reply.classList.remove('is-pending');"
    "bubble.appendChild(reply);"
    "const eventsShell = document.createElement('details');"
    "eventsShell.className = 'turn-cluster-events';"
    "const eventsHead = document.createElement('summary');"
    "eventsHead.className = 'turn-cluster-events-head turn-cluster-events-toggle';"
    "const eventsTitle = document.createElement('span');"
    "eventsTitle.textContent = 'Event Log';"
    "eventsHead.appendChild(eventsTitle);"
    "const eventsCount = document.createElement('span');"
    "eventsCount.textContent = `${cluster.entries.length} entries`;"
