    "meta.className = 'turn-cluster-meta';"
    "meta.textContent = isUserBlock ? 'Queued or submitted user input for this session' : 'System-generated FIFO input and lifecycle events for this session';"
    "headCopy.appendChild(meta);"
    "head.appendChild(headCopy);"
    "const badges = document.createElement('div');"
