    "eventsHead.appendChild(eventsCount);"
    "eventsShell.appendChild(eventsHead);"
    "const log = document.createElement('div');"
    "log.className = 'turn-cluster-log';"
    "log.dataset.scrollKey = clusterRenderKey(cluster);"
    "for (const blockEntry of cluster.entries) {"
    "const row = document.createElement('div');"
    "row.className = 'turn-cluster-log-entry';"
    "const rowHead = document.createElement('div');"
    "rowHead.className = 'turn-cluster-log-entry-head';"
    "const left = document.createElement('span');"
    "left.textContent = turnLogLabel(blockEntry);"
    "rowHead.appendChild(left);"
    "const right = document.createElement('span');"
    "right.textContent = String(blockEntry.ts || '');"
    "rowHead.appendChild(right);"
    "row.appendChild(rowHead);"
    "const rowText = document.createElement('div');"
    "rowText.className = 'turn-cluster-log-entry-text';"
    "rowText.textContent = entryDisplayText(blockEntry);"
    "row.appendChild(rowText);"
    "if (blockEntry?.event) {"
    "const rawShell = document.createElement('details');"
    "rawShell.className = 'turn-cluster-json';"
    "const rawHead = document.createElement('summary');"
    "rawHead.textContent = 'Raw JSON';"
    "rawShell.appendChild(rawHead);"
    "const raw = document.createElement('pre');"
    "raw.className = 'event-json';"
