    "}"
    "eventsShell.appendChild(log);"
    "bubble.appendChild(eventsShell);"
    "li.appendChild(bubble);"
    "return li;"
    "};"
    "const buildRenderableTimeline = (items) => {"
    "const ascending = items.slice().sort((left, right) => String(left?.ts || '').localeCompare(String(right?.ts || '')));"
    "const timeline = [];"
    "const agentClusters = new Map();"
    "let goalCluster = null;"
    "let plainCluster = null;"
    "const finalizeCluster = (sid) => { const c = agentClusters.get(sid); if (!c) return; timeline.push(c); agentClusters.delete(sid); };"
    "const finalizeAllClusters = () => { for (const sid of [...agentClusters.keys()]) finalizeCluster(sid); };"
    "const finalizeGoalCluster = () => { if (!goalCluster) return; timeline.push(goalCluster); goalCluster = null; };"
    "const finalizePlainCluster = () => { if (!plainCluster) return; timeline.push(plainCluster); plainCluster = null; };"
    "for (const entry of ascending) {"
    "const eventType = String(entry?.event_type || '');"
    "const serviceId = entryServiceId(entry);"
    "if (isGoalManagerEntry(entry)) {"
    "finalizePlainCluster();"
    "finalizeAllClusters();"
    "if (!goalCluster) goalCluster = { kind: 'goal_manager_cluster', entries: [] };"
    "goalCluster.entries.push(entry);"
    "continue;"
    "}"
    "finalizeGoalCluster();"
    "const plainKind = plainBlockKind(entry);"
    "if (plainKind) {"
    "finalizeAllClusters();"
    "if (plainCluster && plainCluster.kind !== plainKind) finalizePlainCluster();"
    "if (!plainCluster) plainCluster = { kind: plainKind, entries: [] };"
    "plainCluster.entries.push(entry);"
    "continue;"
    "}"
    "finalizePlainCluster();"
    "if (!isAgentTurnRelatedEntry(entry)) {"
    "timeline.push(entry);"
    "continue;"
    "}"
    "if (eventType === 'agent.turn_started') {"
    "const existing = agentClusters.get(serviceId);"
    "const isEmptyTurnStartedCluster = existing && !existing.replyEntry && !existing.completed && existing.entries.length === 1 && String(existing.entries[0]?.event_type || '') === 'agent.turn_started';"
    "if (isEmptyTurnStartedCluster) { existing.entries = [entry]; } else { if (existing) finalizeCluster(serviceId); agentClusters.set(serviceId, { kind: 'turn_cluster', serviceId, entries: [entry], replyEntry: null, completed: false }); }"
    "continue;"
    "}"
    "let cluster = agentClusters.get(serviceId);"
    "if (!cluster) {"
    "if (serviceId && (entry.direction === 'in' || entry.direction === 'session_input' || entry.direction === 'event' || entry.direction === 'agent')) {"
    "cluster = { kind: 'turn_cluster', serviceId, entries: [], replyEntry: null, completed: false };"
    "agentClusters.set(serviceId, cluster);"
    "} else {"
    "timeline.push(entry);"
    "continue;"
    "}"
    "} else if (cluster.completed && !isAgentScopedStatusEventType(eventType)) {"
    "finalizeCluster(serviceId);"
    "if (serviceId && (entry.direction === 'in' || entry.direction === 'session_input' || entry.direction === 'event' || entry.direction === 'agent')) {"
    "cluster = { kind: 'turn_cluster', serviceId, entries: [], replyEntry: null, completed: false };"
    "agentClusters.set(serviceId, cluster);"
    "} else {"
    "timeline.push(entry);"
    "continue;"
    "}"
    "}"
    "cluster.entries.push(entry);"
    "if (eventType === 'turn.completed') { cluster.completed = true; finalizeCluster(serviceId); } else if (entry.direction === 'in') { cluster.replyEntry = entry; }"
    "}"
    "finalizeAllClusters();"
    "finalizeGoalCluster();"
    "finalizePlainCluster();"
    "return timeline.reverse();"
    "};"
    "const deriveContextStatusForService = (serviceId) => {"
    "const targetServiceId = String(serviceId || '').trim();"
    "for (const entry of entries) {"
    "if (targetServiceId && entryServiceId(entry) !== targetServiceId) continue;"
    "const eventType = String(entry.event_type || '');"
    "const compaction = String(entry.context_compaction || '');"
    "const preLeft = entry.context_left_percent;"
    "const postLeft = entry.context_post_left_percent;"
    "const left = postLeft ?? preLeft;"
    "if ((eventType === 'service.auto_compact_checked' || eventType === 'service.manual_compact_checked') && compaction === 'triggered') {"
    "if (postLeft === undefined || String(postLeft) === String(preLeft ?? '')) {"
    "return {"
    "label: 'Context compacted',"
    "meta: 'Waiting for next context check to refresh the percentage',"
    "compaction,"
    "event_type: eventType,"
    "};"
    "}"
    "}"
    "if (left === undefined) continue;"
    "return {"
    "label: `Context ${String(left)}% left`,"
    "meta: '',"
    "left_percent: String(left),"
    "used_percent: String(entry.context_post_used_percent ?? entry.context_used_percent ?? ''),"
    "compaction,"
    "event_type: eventType,"
    "};"
    "}"
    "return null;"
    "};"
    "const deriveContextStatus = () => deriveContextStatusForService(activeAgentPopoverServiceId || boundServiceId);"
    "const renderContextStatus = () => {"
    "const popoverServiceId = String(activeAgentPopoverServiceId || boundServiceId || '').trim();"
    "const derivedStatus = deriveContextStatusForService(popoverServiceId);"
    "const fallbackStatus = (contextStatus && typeof contextStatus === 'object') ? contextStatus : null;"
    "const resolvedStatus = derivedStatus || fallbackStatus;"
    "if (derivedStatus) contextStatus = derivedStatus;"
    "if (!resolvedStatus) {"
    "contextStatusValue.textContent = 'Context unknown';"
    "contextStatusMeta.textContent = 'AutoCompact waits for first check';"
    "return;"
    "}"
    "contextStatusValue.textContent = resolvedStatus.label || 'Context unknown';"
    "const bits = [];"
    "if (resolvedStatus.meta) bits.push(resolvedStatus.meta);"
    "if (resolvedStatus.compaction) bits.push(`Compaction ${resolvedStatus.compaction}`);"
    "if (resolvedStatus.event_type) bits.push(resolvedStatus.event_type);"
    "contextStatusMeta.textContent = bits.join(' | ') || 'Latest agent-scoped context check';"
    "};"
    "const applyFilterButtons = () => {"
    "for (const button of filterButtons) {"
    "const isActive = button.dataset.filter === currentFilter;"
    "button.classList.toggle('is-active', isActive);"
    "button.classList.toggle('ghost', !isActive);"
    "}"
    "};"
    "const trimEntriesToLimit = () => {"
    "const maxEntries = computeEntryFetchLimit();"
    "while (entries.length > maxEntries) entries.pop();"
    "};"
    "const syncEntriesState = () => {"
    "sortEntriesNewestFirst(entries);"
    "trimEntriesToLimit();"
    "lastEntriesSignature = JSON.stringify(entries);"
    "};"
    "const pushEntryToTimeline = (entry) => {"
    "if (!entry || typeof entry !== 'object') return;"
    "entries.unshift(entry);"
    "syncEntriesState();"
    "renderContextStatus();"
    "renderGoalAuditIndicator();"
    "renderList();"
    "};"
    "const resizeSessionNameTextarea = () => {"
    "sessionNameTextarea.style.height = 'auto';"
    "sessionNameTextarea.style.height = `${Math.max(36, sessionNameTextarea.scrollHeight)}px`;"
    "};"
    "const setWorkspaceLabel = (label) => {"
    "workspaceLabel = label;"
    "if (!sessionNameEditing && document.activeElement !== sessionNameTextarea) {"
    "sessionNameTextarea.value = label;"
    "resizeSessionNameTextarea();"
    "}"
    "renderPageTitle();"
    "renderWorkspaceNavList();"
    "};"
    "const renderRecentMessagesLimit = (statusText = '') => {"
    "recentMessagesLimitInput.value = String(recentMessagesLimit);"
    "recentMessagesLimitValue.textContent = `${String(recentMessagesLimit)} visible`;"
    "recentMessagesLimitStatus.textContent = statusText || `Showing up to ${String(recentMessagesLimit)} timeline entries in this browser.`;"
    "};"
    "const renderAutoCompactThreshold = () => {"
    "const label = `${String(autoCompactThreshold)}%`;"
    "autoCompactThresholdSlider.value = String(autoCompactThreshold);"
    "autoCompactThresholdValue.textContent = label;"
    "};"
    "let _refreshWorkspaceBoardInFlight = false;"
    "let _refreshGoalStateInFlight = false;"
    "let goalEditorDirty = false;"
    "let goalEditorFocused = false;"
    "let sessionNameEditing = false;"
    "const syncGoalEditorDirtyState = () => {"
    "goalEditorDirty = goalEditorText.value !== goalTextValue;"
    "};"
    "const normalizedGoalHistory = () => Array.isArray(goalHistory) ? goalHistory.filter(Boolean) : [];"
    "const syncGoalHistoryCursor = (preferredGoalId = '') => {"
    "const revisions = normalizedGoalHistory();"
    "if (!revisions.length) { goalHistoryCursor = -1; return goalHistoryCursor; }"
    "const targetGoalId = String(preferredGoalId || '').trim();"
    "if (targetGoalId) {"
    "const matchedIndex = revisions.findIndex((revision) => String(revision?.goal_id || '').trim() === targetGoalId);"
    "if (matchedIndex >= 0) { goalHistoryCursor = matchedIndex; return goalHistoryCursor; }"
    "}"
    "if (!Number.isInteger(goalHistoryCursor) || goalHistoryCursor < 0 || goalHistoryCursor >= revisions.length) goalHistoryCursor = revisions.length - 1;"
    "return goalHistoryCursor;"
    "};"
    "const selectedGoalRevision = () => {"
    "const revisions = normalizedGoalHistory();"
    "const index = syncGoalHistoryCursor();"
    "return index >= 0 ? revisions[index] || null : null;"
    "};"
    "const goalRevisionDisplay = () => {"
    "const revisions = normalizedGoalHistory();"
    "const index = syncGoalHistoryCursor();"
    "const revision = index >= 0 ? revisions[index] || null : null;"
    "return { revisions, index, total: revisions.length, revision, isLatest: Boolean(revision) && index === revisions.length - 1, text: String(revision?.goal_text || goalTextValue || '').trim() };"
    "};"
    "const goalSummaryText = () => {"
    "const display = goalRevisionDisplay();"
    "if (display.text) return display.text;"
    "if (!goalTextValue) return 'No goal set for this session.';"
    "return goalTextValue;"
    "};"
    "const renderWelcomedAgents = () => {"
    "if (!welcomedAgentsList) return;"
    "welcomedAgentsList.replaceChildren();"
    "if (!welcomedAgents || welcomedAgents.length === 0) {"
    "const li = document.createElement('li');"
    "li.className = 'welcomed-agents-empty';"
    "li.textContent = 'No agents welcomed yet.';"
    "welcomedAgentsList.appendChild(li);"
    "return;"
    "}"
    "for (const agent of welcomedAgents) {"
    "const li = document.createElement('li');"
    "li.className = 'welcomed-agent-item';"
    "const sid = String(agent.service_id || '');"
    "const prov = String(agent.provider || '');"
    "const lastTurn = String(agent.last_turn_completed_at || '');"
    "li.innerHTML = `<span class='welcomed-agent-id'>${sid}</span><span class='welcomed-agent-provider'>${prov}</span>${lastTurn ? `<span class='welcomed-agent-turn'>last turn ${lastTurn.slice(0,19).replace('T',' ')}</span>` : '<span class=\"welcomed-agent-turn\">no turns yet</span>'}`;"
    "welcomedAgentsList.appendChild(li);"
    "}"
    "};"
    "const renderActiveAgentsSelection = () => {"
    "const allDiv = document.getElementById('agent-select-all');"
    "if (!allDiv) return;"
    "allDiv.replaceChildren();"
    "const localSids = new Set(localServices.map(s => s.service_id));"
    "const wsPeerSids = new Set();"
    "for (const agent of welcomedAgents) {"
    "const sid = String(agent.service_id || '');"
    "if (sid && !localSids.has(sid)) wsPeerSids.add(sid);"
    "}"
    "const allEntries = ["
    "...localServices.map(s => ({ sid: s.service_id, kind: s.kind, label: s.service_id })),"
    "...[...wsPeerSids].map(sid => ({ sid, kind: 'ws_peer', label: sid })),"
    "];"
    "for (const entry of allEntries) {"
    "const lbl = document.createElement('label');"
    "lbl.className = 'agent-select-item';"
    "const cb = document.createElement('input');"
    "cb.type = 'checkbox';"
    "cb.value = entry.sid;"
    "cb.className = 'agent-select-cb';"
    "cb.checked = selectedAgents.includes(entry.sid);"
    "cb.addEventListener('change', handleActiveAgentsChange);"
    "const span = document.createElement('span');"
    "span.className = 'agent-select-label';"
    "span.textContent = entry.label;"
    "if (entry.kind === 'ws_peer') span.style.fontStyle = 'italic';"
    "lbl.appendChild(cb);"
    "lbl.appendChild(span);"
    "allDiv.appendChild(lbl);"
    "}"
    "const statusEl = document.getElementById('active-agents-status');"
    "if (statusEl) statusEl.textContent = '';"
    "};"
    "const collectActiveAgents = () => {"
    "const list = [];"
    "for (const cb of document.querySelectorAll('.agent-select-cb')) {"
    "if (cb.checked) list.push(String(cb.value));"
    "}"
    "return list;"
    "};"
    "let activeAgentsMutationInFlight = false;"
    "const handleActiveAgentsChange = async () => {"
    "if (activeAgentsMutationInFlight) return;"
    "const next = collectActiveAgents();"
    "activeAgentsMutationInFlight = true;"
    "const statusEl = document.getElementById('active-agents-status');"
    "if (statusEl) statusEl.textContent = 'Saving…';"
    "try {"
    "const response = await fetch('/session/selected-agents', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: activeSessionId, selected_agents: next }) });"
    "const payload = await response.json().catch(() => ({}));"
    "if (!response.ok || !payload.ok) {"
    "if (statusEl) statusEl.textContent = `Save failed: ${payload.error || `HTTP ${response.status}`}`;"
    "renderActiveAgentsSelection();"
    "return;"
    "}"
    "selectedAgents = Array.isArray(payload.selected_agents) ? payload.selected_agents : next;"
    "renderActiveAgentsSelection();"
    "} catch (err) {"
    "if (statusEl) statusEl.textContent = `Save failed: ${err}`;"
    "renderActiveAgentsSelection();"
    "} finally {"
    "activeAgentsMutationInFlight = false;"
    "}"
    "};"
    "const renderSessionStatusStrip = () => {"
    "if (!sessionStatusStrip && !composerDockMeta) return;"
    "const hasGoal = Boolean(goalTextValue);"
    "const progressText = goalCompleted ? 'Goal Completed' : (goalProgressState === 'complete' ? 'Goal Completed' : 'Goal In Progress');"
    "const runtimeText = runtimeExecutionState === 'running' ? 'Executing' : (runtimeExecutionState === 'failed' ? 'Runtime Failed' : 'Runtime Idle');"
    "const runtimeClass = runtimeExecutionState === 'running' ? 'is-running' : (runtimeExecutionState === 'failed' ? 'is-audit-panic' : '');"
    "const waitText = userResponseWaitStartedAt ? (userResponseWaitActive ? 'Waiting for User' : (userResponseWaitStatus === 'timed_out' ? 'Wait Timed Out' : 'Wait Recorded')) : '';"
    "const auditChip = `<span class=\"session-status-chip ${auditStateBadgeClass(goalAuditState)}\">${auditStateLabel(goalAuditState)}</span>`;"
    "const chips = ["
    "hasGoal ? `<span class=\"session-status-chip ${goalActive ? 'is-active' : ''}\">${goalActive ? 'Goal Active' : 'Goal Inactive'}</span>` : `<span class=\"session-status-chip\">No Goal</span>`,"
    "`<span class=\"session-status-chip ${progressText === 'Goal Completed' ? 'is-complete' : ''}\">${progressText}</span>`,"
    "`<span class=\"session-status-chip ${runtimeClass}\">${runtimeText}</span>`,"
    "auditChip,"
    "waitText ? `<span class=\"session-status-chip is-waiting\">${waitText}</span>` : '',"
    "];"
    "if (sessionStatusStrip) sessionStatusStrip.innerHTML = chips.filter(Boolean).join('');"
    "if (composerDockMeta) composerDockMeta.innerHTML = ["
    "`<span class=\"composer-dock-chip ${goalActive ? 'is-active' : ''}\">${goalActive ? 'Goal Active' : 'Goal Inactive'}</span>`,"
    "`<span class=\"composer-dock-chip ${goalProgressState === 'complete' ? 'is-complete' : 'is-running'}\">${goalProgressState === 'complete' ? 'Completed' : 'In Progress'}</span>`,"
    "`<span class=\"composer-dock-chip ${auditStateBadgeClass(goalAuditState)}\">${auditStateLabel(goalAuditState)}</span>`,"
    "goalManagerRuntimeState === 'running' ? `<span class=\"composer-dock-chip is-running\">Running</span>` : '',"
    "userResponseWaitStatus && userResponseWaitStatus !== 'idle' ? `<span class=\"composer-dock-chip is-waiting\">${userResponseWaitActive ? 'Waiting for User' : userResponseWaitStatus}</span>` : '',"
    "].filter(Boolean).join('');"
    "if (composerDockLabel) composerDockLabel.textContent = sessionPermissionAllowed('send_prompt') ? `Send to the active ${providerLabel()} service` : 'Prompt disabled for this session';"
    "};"
    "const renderGoalState = () => {"
    "const display = goalRevisionDisplay();"
    "const hasGoal = Boolean(goalTextValue);"
    "if (workspaceGoalStateText instanceof HTMLTextAreaElement) workspaceGoalStateText.value = goalSummaryText(); else workspaceGoalStateText.textContent = goalSummaryText();"
    "if (!goalEditorDirty && !goalEditorFocused && !goalPopoverOpen && document.activeElement !== goalEditorText) goalEditorText.value = goalTextValue;"
    "const stateSummary = hasGoal ? `${goalActive ? 'Goal Active' : 'Goal Inactive'} | ${goalProgressState === 'complete' ? 'Goal Completed' : 'Goal In Progress'}` : 'No Goal';"
    "const waitSummary = userResponseWaitStartedAt ? ` | ${userResponseWaitActive ? 'User Wait' : (userResponseWaitStatus === 'timed_out' ? 'Wait Timed Out' : 'Wait Recorded')}` : '';"
    "const revisionMetaPrefix = display.total ? `${stateSummary}${waitSummary} | Showing ${display.isLatest ? 'current' : 'past'} revision ${display.index + 1}/${display.total}${display.revision ? ` | ${formatGoalHistoryMeta(display.revision)}` : ''}. ` : `${stateSummary}${waitSummary}. `;"
    "if (!hasGoal) {"
    "workspaceGoalStateMeta.textContent = `${revisionMetaPrefix}Goal mode saves the session goal. Manager is idle until a goal exists.`.trim();"
    "} else if (goalCompleted) {"
    "workspaceGoalStateMeta.textContent = goalActive ? `${revisionMetaPrefix}Manager marked this session completed. SendPrompt reset is ${goalResetCompletedOnPrompt ? 'ON' : 'OFF'}. Auto compact is ${goalAutoCompactEnabled ? 'ON' : 'OFF'}.`.trim() : `${revisionMetaPrefix}Completed goal kept inactive until you update it.`.trim();"
    "} else if (goalActive) {"
