    "if (nodesConnectStatus) { nodesConnectStatus.dataset.busy = '1'; nodesConnectStatus.textContent = `Connecting ${peerUrl}...`; }"
    "if (nodesConnectButton) nodesConnectButton.disabled = true;"
    "try {"
    "const response = await fetch('/peer/ping', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ peer_url: peerUrl }) });"
    "const payload = await response.json().catch(() => ({}));"
    "if (!response.ok || !payload.ok) throw new Error(String(payload.error || `HTTP ${response.status}`));"
    "const peer = payload?.to && typeof payload.to === 'object' ? payload.to : {};"
    "const nodeId = String(peer?.node_id || '').trim();"
    "const peerId = String(peer?.peer_id || '').trim();"
    "const baseUrl = String(peer?.base_url || peerUrl).trim().replace(/\\/$/, '');"
    "if (nodeId && baseUrl) {"
    "const connectResponse = await fetch('/federation/connect', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ node_id: nodeId, peer_id: peerId, base_url: baseUrl, started_at: String(peer?.started_at || ''), reciprocal: true }) });"
    "const connectPayload = await connectResponse.json().catch(() => ({}));"
    "if (!connectResponse.ok || !connectPayload.ok) throw new Error(String(connectPayload.error || `connect HTTP ${connectResponse.status}`));"
    "}"
    "if (nodesConnectStatus) nodesConnectStatus.textContent = `Connected ${nodeId || peerId || peerUrl}.`;"
    "if (nodesConnectForm) nodesConnectForm.reset();"
    "await refreshNetworkNodes();"
    "} catch (error) {"
    "if (nodesConnectStatus) nodesConnectStatus.textContent = `Connect failed: ${error instanceof Error ? error.message : 'network error'}`;"
    "} finally {"
    "if (nodesConnectStatus) delete nodesConnectStatus.dataset.busy;"
    "if (nodesConnectButton) nodesConnectButton.disabled = false;"
    "}"
    "});"
    "refreshUnitCatalog();"
    "renderRuntimeJournalMeta();"
    "if (runtimeJournalPanel) runtimeJournalPanel.addEventListener('toggle', async () => {"
    "if (!runtimeJournalPanel.open || runtimeJournalLoadedForSession === activeSessionId) return;"
    "if (runtimeJournalLog) runtimeJournalLog.innerHTML = \"<div class='runtime-journal-empty'>Loading runtime events...</div>\";"
    "try { await fetchRuntimeJournal({ entries: true }); }"
    "catch (error) { if (runtimeJournalLog) runtimeJournalLog.innerHTML = `<div class='runtime-journal-empty'>Runtime log load failed: ${escapeHtml(error instanceof Error ? error.message : 'network error')}</div>`; }"
    "});"
    "window.setInterval(() => { if (!document.hidden) refreshGoalState(); }, 5000);"
    "window.setInterval(() => { if (!document.hidden && unitsPaneOpen) refreshUnitCatalog(); }, 15000);"
