    "const workspaceGoalCollapsedStorageKey = getWorkspaceGoalCollapsedStorageKey(activeSessionId);"
    "const workspaceGoalCollapsed = localStorage.getItem(workspaceGoalCollapsedStorageKey) === '1';"
    "workspaceGoalPanel.classList.toggle('is-collapsed', workspaceGoalCollapsed);"
    "workspaceGoalToggle.setAttribute('aria-expanded', workspaceGoalCollapsed ? 'false' : 'true');"
