    "});"
    "let _renameDebounce = null;"
    "const scheduleAutoRename = (delay = 1200) => {"
    "clearTimeout(_renameDebounce);"
    "if (sessionNameIsComposing) return;"
    "_renameDebounce = setTimeout(doAutoRename, delay);"
    "};"
    "const doAutoRename = async () => {"
    "if (sessionNameIsComposing) return;"
    "const newLabel = sessionNameTextarea.value.trim();"
    "if (!newLabel || newLabel === workspaceLabel) return;"
    "try {"
    "const response = await fetch('/session/rename', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: activeSessionId, label: newLabel }) });"
    "if (response.ok) { setWorkspaceLabel(newLabel); }"
    "} catch (e) {}"
    "};"
    "if (sessionNameWrap) sessionNameWrap.addEventListener('click', (event) => {"
    "const target = event.target;"
    "if (target instanceof HTMLElement && (target.closest('button') || target.closest('a') || target.closest('input') || target.closest('select'))) return;"
    "if (document.activeElement !== sessionNameTextarea) {"
    "requestAnimationFrame(() => { try { sessionNameTextarea.focus({ preventScroll: true }); } catch (_e) { sessionNameTextarea.focus(); } });"
    "}"
    "});"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('pointerdown', () => {"
    "if (document.activeElement !== sessionNameTextarea) {"
    "requestAnimationFrame(() => { try { sessionNameTextarea.focus({ preventScroll: true }); } catch (_e) { sessionNameTextarea.focus(); } });"
    "}"
    "});"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('focus', () => { sessionNameEditing = true; });"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('compositionstart', () => { sessionNameIsComposing = true; clearTimeout(_renameDebounce); });"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('compositionend', () => { sessionNameIsComposing = false; resizeSessionNameTextarea(); if (document.activeElement === sessionNameTextarea) { scheduleAutoRename(250); } else { doAutoRename(); } });"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('blur', () => { sessionNameEditing = false; if (sessionNameIsComposing) return; doAutoRename(); });"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('input', () => { resizeSessionNameTextarea(); if (sessionNameIsComposing) return; scheduleAutoRename(); });"
    "if (sessionNameTextarea) sessionNameTextarea.addEventListener('keydown', (ev) => { if (ev.key === 'Enter' && !ev.shiftKey) { if (sessionNameIsComposing || ev.isComposing || ev.keyCode === 229) return; ev.preventDefault(); sessionNameTextarea.blur(); } });"
    "if (agentCloseButton) agentCloseButton.addEventListener('click', () => {"
    "setAgentPopoverOpen(false);"
    "});"
    "document.addEventListener('click', (event) => {"
    "const target = event.target;"
    "if (!(target instanceof Node)) return;"
    "const clickedAgentButton = target.closest ? target.closest('[data-agent-controls-button=\"1\"]') : null;"
    "if (clickedAgentButton) {"
    "const targetServiceId = String(clickedAgentButton.getAttribute('data-agent-service-id') || activeAgentPopoverServiceId || boundServiceId || '').trim();"
    "event.preventDefault();"
    "event.stopPropagation();"
    "setAgentPopoverOpen(true, targetServiceId);"
    "return;"
    "}"
    "if (goalPopoverOpen && goalPopover && !((goalPopoverCard || goalPopover).contains(target) || (viewGoalButton && viewGoalButton.contains(target)))) {"
    "setGoalPopoverOpen(false);"
    "}"
    "if (settingsPopover && !settingsPopover.classList.contains('is-hidden') && !((settingsPopoverCard || settingsPopover).contains(target) || (viewSettingsButton && viewSettingsButton.contains(target)))) {"
    "setSettingsPopoverOpen(false);"
    "}"
    "if (agentPopoverOpen && !((agentPopoverCard || agentPopover).contains(target) || clickedAgentButton)) {"
    "setAgentPopoverOpen(false);"
    "}"
    "});"
    "document.addEventListener('keydown', (event) => {"
    "if (event.key !== 'Escape') return;"
    "if (goalPopoverOpen) { setGoalPopoverOpen(false); viewGoalButton.focus(); }"
    "if (settingsPopover && !settingsPopover.classList.contains('is-hidden')) { setSettingsPopoverOpen(false); if (viewSettingsButton) viewSettingsButton.focus(); }"
    "if (agentPopoverOpen) { setAgentPopoverOpen(false); }"
    "});"
    "const handleProviderSelectChange = async () => {"
    "if (providerMutationInFlight) return;"
    "const nextProvider = String(providerSelect.value || 'codex');"
    "providerMutationInFlight = true;"
    "providerStatus.textContent = `Saving provider ${nextProvider}...`;"
    "try {"
    "const response = await fetch('/session/goal/state', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: activeSessionId, preferred_provider: nextProvider }) });"
    "const payload = await response.json().catch(() => ({}));"
    "if (!response.ok || !payload.ok) {"
    "providerSelect.value = preferredProvider;"
    "providerStatus.textContent = `Provider save failed: ${payload.error || `HTTP ${response.status}`}`;"
    "return;"
    "}"
    "goalTextValue = Object.prototype.hasOwnProperty.call(payload, 'goal_text') ? String(payload.goal_text || '') : goalTextValue;"
    "if (!goalEditorFocused && !goalEditorDirty) { goalEditorDirty = false; goalEditorText.value = goalTextValue; } else { syncGoalEditorDirtyState(); }"
    "goalActive = Boolean(payload.goal_active);"
    "goalCompleted = Boolean(payload.goal_completed);"
    "goalProgressState = String(payload.goal_progress_state || (goalCompleted ? 'complete' : 'in_progress'));"
    "goalAuditState = String(payload.goal_audit_state || goalAuditState || 'all_clear');"
    "goalManagerRuntimeState = String(payload.goal_manager_state || goalManagerRuntimeState || 'idle');"
    "runtimeExecutionState = String(payload.runtime_execution_state || (payload.runtime_in_progress ? 'running' : runtimeExecutionState || 'idle'));"
    "goalResetCompletedOnPrompt = Boolean(payload.goal_reset_completed_on_prompt ?? goalResetCompletedOnPrompt);"
    "goalAutoCompactEnabled = Boolean(payload.goal_auto_compact_enabled ?? goalAutoCompactEnabled);"
    "preferredProvider = String(payload.preferred_provider || nextProvider);"
    "renderGoalState();"
    "renderViewMode();"
    "providerStatus.textContent = `${providerLabel()} selected for this session`;"
    "} catch (error) {"
    "providerSelect.value = preferredProvider;"
    "providerStatus.textContent = `Provider save failed: ${error}`;"
